aerith-gainsborough.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const aerithGainsborough: CardDefinition = {
  name: 'Aerith Gainsborough',
  manaCost: '{2}{W}',
  typeLine: 'Legendary Creature — Human Cleric',

  keywords: ['Lifelink'],

  triggers: [
    {
      name: 'onLifeGained',
      effects: [{ kind: 'putCounter', target: 'self', counterType: '+1/+1', amount: 1 } satisfies Effect],
    },
    {
      name: 'onDies',
      effects: [
        {
          kind: 'custom',
          describe:
            'put X +1/+1 counters on each legendary creature you control, where X is the number of +1/+1 counters on this (real getCounters(), not a fixed/guessed value)',
          run: (ctx: EffectContext, actions: Actions) => {
            const x = ctx.self.getCounters('+1/+1');
            if (x <= 0) return;
            // Real Forge tracks "Legendary" as a SUPERTYPE, distinct from
            // this model's coarse types/subtypes (state.ts's RealCard has
            // neither) — hasSubtype('Legendary') is a pragmatic
            // approximation of that check, not a real supertype lookup.
            const legendaries = ctx.you.getCreaturesInPlay().filter((c) => c.hasSubtype('Legendary'));
            for (const creature of legendaries) actions.putCounter(creature, '+1/+1', x);
          },
        } satisfies Effect,
      ],
    },
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header). Neither
// onLifeGained nor onDies auto-fires in this engine — each real underlying
// event happens for real, then the matching trigger fires manually.

import { aerithGainsborough } from './definition';
import { basicLandsFor } from '../../mana';
import { checkStateBasedActions } from '../../sba';
import { effectivePT } from '../../state';
import type { TraceResult } from '../../harness';
import { resolveCombatDamage } from '../../engine';
import {
  setupEnginePilot,
  pilotActions,
  pilotCast,
  pilotResolveTop,
  advanceToPlayersNextMain1,
  advanceToDeclareAttackersStep,
  advanceOneStep,
  pilotDeclareAttackers,
  pilotDeclareBlockers,
  pilotFireTrigger,
  finishEnginePilotTrace,
  type EnginePilotSetup,
} from '../../engine-trace';

export function runEngineScenarios(): TraceResult[] {
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{2}{W}'), libraryCount: 8 },
    opponents: [{ libraryCount: 8 }],
  };
  const pilot = setupEnginePilot(setup);

  const aerithReal = pilot.state.addCard(pilot.you, 'Hand', {
    name: aerithGainsborough.name,
    types: ['Creature'],
    subtypes: ['Human', 'Cleric', 'Legendary'],
    keywords: aerithGainsborough.keywords,
    basePower: 1,
    baseToughness: 3,
  });
  // Freya Crescent (data/fin/fin_scryfall.json: {R} Legendary Creature — Rat
  // Knight, 1/1) — onDies below needs a real OTHER legendary creature you
  // control for its "spread X counters onto each legendary creature you
  // control" effect (definition.ts's own onDies, `hasSubtype('Legendary')`)
  // to have something real to land on.
  const otherLegend = pilot.state.addCard(pilot.you, 'Battlefield', {
    name: 'Freya Crescent',
    types: ['Creature'],
    subtypes: ['Legendary', 'Rat', 'Knight'],
    basePower: 1,
    baseToughness: 1,
  });
  // A real `enters` entry for each bystander — without one, it never shows
  // up on the replay board at all until (if ever) some LATER effect happens
  // to reference it by name, appearing out of nowhere at that point instead
  // of having been visibly present since setup.
  pilot.log.push({ fn: 'enters', card: otherLegend.name, zone: 'Battlefield', power: otherLegend.basePower, toughness: otherLegend.baseToughness });
  // Gigantoad (data/fin/fin_scryfall.json: {3}{G} Creature — Frog, 4/4) — its
  // own "control seven or more lands" static buff is inert here (it's placed
  // directly via addCard, never cast, so it isn't wired to any
  // CardDefinition/continuous-effect registration the engine would evaluate;
  // only its printed base 4/4 matters).
  const bigBlocker = pilot.state.addCard(pilot.opponents[0]!, 'Battlefield', {
    name: 'Gigantoad',
    types: ['Creature'],
    subtypes: ['Frog'],
    // 4 power — Aerith is already 2/4 by the time this blocks (her earlier
    // onLifeGained put a real +1/+1 counter on her), so 3 wouldn't be real lethal.
    basePower: 4,
    baseToughness: 4,
  });
  pilot.log.push({
    fn: 'enters',
    card: bigBlocker.name,
    zone: 'Battlefield',
    power: bigBlocker.basePower,
    toughness: bigBlocker.baseToughness,
    controller: pilot.opponents[0]!.name,
  });
  const actions = pilotActions(pilot, aerithReal.id);
  const ctx = pilot.ctxFor(aerithReal);

  // Cast Aerith ({2}{W}), real mana payment
  pilotCast(pilot, aerithReal, aerithGainsborough, ctx, actions);
  pilotResolveTop(pilot);

  // Real turn passage — summoning sickness clears
  advanceToPlayersNextMain1(pilot, pilot.you);

  // Real unblocked combat — real Lifelink life gain, then onLifeGained fired manually
  advanceToDeclareAttackersStep(pilot);
  pilotDeclareAttackers(pilot, [aerithReal], 'Declare Aerith as attacker');
  advanceOneStep(pilot);
  pilotDeclareBlockers(pilot, []);
  pilot.beginStep('Resolve unblocked combat damage — real Lifelink');
  const opp = pilot.opponents[0]!;
  const beforeOppLife = opp.life;
  const beforeYouLife = pilot.you.life;
  resolveCombatDamage(pilot.engine);
  // The real combat damage itself (509/510) — not just its Lifelink side
  // effect. Without this, the replay only ever showed the life GAIN with no
  // visible cause on the opponent's side (confirmed the hard way: looked
  // like Aerith "did nothing" even though she just hit face for 2).
  const damageDealt = beforeOppLife - opp.life;
  if (damageDealt > 0) pilot.log.push({ fn: 'dealDamage', source: aerithReal.name, target: opp.name, amount: damageDealt });
  const lifeGained = pilot.you.life - beforeYouLife;
  if (lifeGained > 0) pilot.log.push({ fn: 'gainLife', player: pilot.you.name, amount: lifeGained, cause: 'Lifelink' });
  pilotFireTrigger(pilot, aerithGainsborough, ctx, actions, 'onLifeGained');

  // Real turn passage, then real combat again — this time blocked and lethal (704.5g SBA)
  advanceToPlayersNextMain1(pilot, pilot.you);
  advanceToDeclareAttackersStep(pilot);
  pilotDeclareAttackers(pilot, [aerithReal], 'Declare Aerith as attacker (blocked this time)');
  advanceOneStep(pilot);
  pilotDeclareBlockers(pilot, [{ blocker: bigBlocker, attacker: aerithReal }]);
  pilot.beginStep('Resolve lethal combat damage (704.5g SBA)');
  // Real 510.1c — both combatants deal damage simultaneously. Read power
  // BEFORE it resolves (damage itself never changes power, but reading
  // after would be one step removed from what actually caused it).
  const aerithPower = effectivePT(pilot.state, aerithReal)[0];
  const blockerPower = effectivePT(pilot.state, bigBlocker)[0];
  resolveCombatDamage(pilot.engine);
  if (aerithPower > 0) pilot.log.push({ fn: 'dealDamage', source: aerithReal.name, target: bigBlocker.name, amount: aerithPower });
  if (blockerPower > 0) pilot.log.push({ fn: 'dealDamage', source: bigBlocker.name, target: aerithReal.name, amount: blockerPower });
  // Real 400.7 wipes counters on zone change — capture this before SBA
  // moves her to the graveyard, so onDies's own "X = counters on this" read
  // has real 603.10 last-known-information to restore, not an already-zeroed count.
  const lastKnownCounters = aerithReal.counters['+1/+1'] ?? 0;
  const sbaResult = checkStateBasedActions(pilot.state, pilot.engine.players);
  // `destroyed`'s own real controller (704.5g can kill EITHER combatant,
  // even though Gigantoad's 4 toughness happens to survive this particular
  // exchange) — hardcoding `pilot.you.name` here would be wrong whenever the
  // destroyed permanent is the OPPONENT's own creature, and
  // verify-synergy.mjs's own `sideOf` trusts a present `controller` field
  // over any name-based guessing, so a wrong one here would misattribute
  // which SIDE this destroy fact supports.
  for (const destroyed of sbaResult.destroyed) {
    const controllerName = pilot.state.players.get(destroyed.controllerId)!.name;
    pilot.log.push({ fn: 'destroy', target: destroyed.name, controller: controllerName });
  }

  if (aerithReal.zone === 'Graveyard') {
    aerithReal.counters['+1/+1'] = lastKnownCounters;
    pilotFireTrigger(pilot, aerithGainsborough, ctx, actions, 'onDies');
  }

  const result =
    'Aerith enters; real turn passage clears summoning sickness, then attacks unblocked, gaining real Lifelink life — onLifeGained fires manually, putting a real +1/+1 counter on herself; another real turn later she attacks again, blocked by a creature that deals real lethal damage back (a genuine 704.5g SBA destruction) — onDies then fires manually, spreading X real +1/+1 counters onto the other legendary creature on the battlefield.';
  return [finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast -> real Lifelink -> onLifeGained -> real lethal combat (SBA) -> onDies', result)];
}

aerith-rescue-mission.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';
import type { Card } from '../../interfaces';
import { TOKENS } from '../../tokens.ts';

export const aerithRescueMission: CardDefinition = {
  name: 'Aerith Rescue Mission',
  manaCost: '{3}{W}',
  typeLine: 'Sorcery',

  effects: [
    {
      kind: 'modal',
      modes: [
        {
          describe: 'Take the Elevator — create three 1/1 colorless Hero creature tokens',
          effects: [{ kind: 'createToken', token: TOKENS.c_1_1_hero, amount: 3 } satisfies Effect],
        },
        {
          describe: 'Take 59 Flights of Stairs — tap up to three target creatures, put a stun counter on one of them',
          effects: [
            {
              // Tap-N-then-counter-ONE-of-those-N needs the same chosen
              // targets bound across two steps — no declarative shape here
              // supports referencing "one of the targets from the PREVIOUS
              // effect," so this stays one combined custom rather than a
              // `tapTarget` followed by a `putCounterTarget` that can't
              // actually see which cards the first one picked.
              kind: 'custom',
              describe: 'tap up to three target creatures, then put a stun counter on one of them',
              run: (ctx: EffectContext, actions: Actions) => {
                const pool = [...ctx.you.getCreaturesInPlay(), ...ctx.opponents.flatMap((p) => p.getCreaturesInPlay())];
                const tapped: Card[] = [];
                for (let i = 0; i < 3; i++) {
                  const remaining = pool.filter((c) => !tapped.includes(c));
                  if (remaining.length === 0) break;
                  const target = actions.chooseTarget(remaining);
                  tapped.push(target);
                  actions.tap(target);
                }
                if (tapped.length > 0) actions.putCounter(tapped[0]!, 'stun', 1);
              },
            } satisfies Effect,
          ],
        },
      ],
    } satisfies Effect,
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header) — a plain
// modal sorcery, one real scenario per mode.

import { aerithRescueMission } from './definition';
import { basicLandsFor } from '../../mana';
import type { TraceResult } from '../../harness';
import { setupEnginePilot, pilotActions, pilotCast, pilotResolveTop, finishEnginePilotTrace, type EnginePilotSetup } from '../../engine-trace';

function elevatorMode(): TraceResult {
  const setup: EnginePilotSetup = { you: { basicLands: basicLandsFor('{3}{W}') } };
  const pilot = setupEnginePilot(setup);
  const cardReal = pilot.state.addCard(pilot.you, 'Hand', { name: aerithRescueMission.name, types: [] });
  const actions = pilotActions(pilot, cardReal.id);
  const ctx = pilot.ctxFor(cardReal, { mode: 0 });

  pilotCast(pilot, cardReal, aerithRescueMission, ctx, actions);
  pilotResolveTop(pilot);

  const result = 'Take the Elevator — creates three real 1/1 colorless Hero creature tokens.';
  return finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast -> mode 0 (Take the Elevator)', result);
}

function stairsMode(): TraceResult {
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{3}{W}'), tokens: ['c_1_1_hero'] },
    opponents: [{ tokens: ['w_1_1_cat'] }],
  };
  const pilot = setupEnginePilot(setup);
  const cardReal = pilot.state.addCard(pilot.you, 'Hand', { name: aerithRescueMission.name, types: [] });
  const actions = pilotActions(pilot, cardReal.id);
  const ctx = pilot.ctxFor(cardReal, { mode: 1 });

  pilotCast(pilot, cardReal, aerithRescueMission, ctx, actions);
  pilotResolveTop(pilot);

  const result = "Take 59 Flights of Stairs — real creatures on the battlefield get tapped (up to three targets), and the first one tapped gets a real stun counter.";
  return finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast -> mode 1 (Take 59 Flights of Stairs)', result);
}

export function runEngineScenarios(): TraceResult[] {
  return [elevatorMode(), stairsMode()];
}

aettir-and-priwen.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

// Real script (aettir_and_priwen.txt): a real layer-7 continuous effect on
// the EQUIPPED creature — "Equipped creature has base power and toughness
// X/X, where X is your life total" (S:Mode$ Continuous | SetPower$ X |
// SetToughness$ X | SVar:X:Count$YourLifeTotal). `CardDefinition.ptFormula`
// only covers a CDA on `self`'s OWN P/T (state.ts's own `effectivePT`
// reads `card.ptFormula` for that same card, never a card it's attached
// to) — there's no mechanism anywhere in this model for an Equipment to
// grant a dynamic, life-total-driven P/T override to whatever it's
// attached to. Kept as real text only, same treatment every other
// Equipment's own static P/T bonus gets (dark-knight-s-greatsword/
// samurai-s-katana/thief-s-knife/buster-sword/excalibur-ii, e.g.) — this
// one's just dynamic instead of a fixed delta, which changes nothing about
// where it has to live.
export const aettirAndPriwen: CardDefinition = {
  name: 'Aettir and Priwen',
  manaCost: '{6}',
  typeLine: 'Legendary Artifact — Equipment',

  staticAbilities: ['Equipped creature has base power and toughness X/X, where X is your life total.'],

  // Equip {5} — the standard Equip ability, same attach-to-a-chosen-
  // creature shape as dragoon-s-lance/thief-s-knife/machinist-s-arsenal.
  activationCost: '{5}',
  effects: [
    {
      kind: 'custom',
      describe: 'attach to target creature you control',
      run: (ctx: EffectContext, actions: Actions) => {
        const target = actions.chooseTarget(ctx.you.getCreaturesInPlay());
        if (target) actions.equip(ctx.self, target);
      },
    } satisfies Effect,
  ],
};

