  // attach-to-a-chosen-creature shape dragoon-s-lance/paladin-s-arms/
  // machinist-s-arsenal/ninja-s-blades already use.
  activationCost: '{2}',
  effects: [
    {
      kind: 'custom',
      describe: 'attach to target creature you control',
      run: (ctx: EffectContext, actions: Actions) => {
        const target = actions.chooseTarget(ctx.you.getCreaturesInPlay());
        if (target) actions.equip(ctx.self, target);
      },
    } satisfies Effect,
  ],
};

auron-s-inspiration.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const auronSInspiration: CardDefinition = {
  name: "Auron's Inspiration",
  manaCost: '{2}{W}',
  typeLine: 'Instant',

  alternateCosts: [{ name: 'Flashback', cost: '{2}{W}{W}', from: 'graveyard', thenExile: true }],

  effects: [
    {
      // "Attacking creatures get +2/+0" is symmetric (ANY player's
      // attacking creatures, no +YouCtrl qualifier) AND depends on combat
      // state this model's EFFECT-RESOLUTION layer specifically can't see
      // (corrected 2026-09-11 — the earlier version of this comment claimed
      // "no attack-declaration step exists at all," which is stale: real
      // attacker state DOES exist, `engine.ts`'s own `GameEngine.attackers`,
      // set by `declareAttackers`/read by `resolveCombatDamage`, real code
      // other cards' own `runEngineScenarios` already pilot — aerith-
      // gainsborough's own combat scenario, e.g.). The gap is narrower and
      // structural: `card.ts`'s `Effect`/`EffectContext`/`Actions` surface
      // (what THIS function can see) is deliberately engine-agnostic — no
      // `GameEngine` reference reaches here, and neither `interfaces.ts`'s
      // `Card`/`Player` nor `pumpAll`'s own predicate union
      // ('creatures-you-control' only, and only YOUR creatures) has any
      // "is this creature currently attacking" read at all, for anyone's
      // creatures. Closing this for real means new interface surface
      // (`Card.isAttacking()` or similar) PLUS wiring `state.ts`'s
      // `wrapCard`/`loggingCard` to actually consult `engine.attackers`
      // (which today only `engine.ts` itself holds) PLUS a new `pumpAll`
      // predicate broadcasting across `ctx.you` AND `ctx.opponents` rather
      // than `ctx.you` alone — a real, cross-cutting engine extension no
      // other FIN card has ever needed, not a one-card `definition.ts` fix;
      // out of scope for this migration, left as an honest custom no-op
      // rather than fabricated. (Flashback, this card's OTHER real ability,
      // IS fully real now — see `alternateCosts` above and `engine.ts`'s own
      // `canCastSpell`/`castSpell`'s `alt` param, ENGINE_GAPS.md gap #7.)
      kind: 'custom',
      describe: 'attacking creatures get +2/+0 until end of turn (no live attacker state reaches the effect-resolution layer in this model — see comment above)',
      run: (_ctx: EffectContext, _actions: Actions) => {
        // Intentionally a no-op — see describe above.
      },
    } satisfies Effect,
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header). The
// "attacking creatures get +2/+0" effect is an intentional no-op (see
// definition.ts's own comment — no combat-attacker-state tracked in this
// model), so real coverage of the main cast is just the cast+resolve
// itself. Flashback IS demonstrated (2026-09-11) — `canCastSpell`/
// `castSpell`/`pilotCast` gained a real, narrow alternate-cost path
// (ENGINE_GAPS.md gap #7, narrowed) for exactly this shape: a fixed
// replacement mana cost, paid from the graveyard, `thenExile` on
// resolution.

import { auronSInspiration } from './definition';
import { basicLandsFor } from '../../mana';
import type { TraceResult } from '../../harness';
import { setupEnginePilot, pilotActions, pilotCast, pilotResolveTop, finishEnginePilotTrace, type EnginePilotSetup } from '../../engine-trace';

function normalCast(): TraceResult {
  const setup: EnginePilotSetup = { you: { basicLands: basicLandsFor('{2}{W}') } };
  const pilot = setupEnginePilot(setup);
  const cardReal = pilot.state.addCard(pilot.you, 'Hand', { name: auronSInspiration.name, types: [] });
  const actions = pilotActions(pilot, cardReal.id);
  const ctx = pilot.ctxFor(cardReal);

  // Cast ({2}{W}), real mana payment
  pilotCast(pilot, cardReal, auronSInspiration, ctx, actions);
  // Resolves — its own effect is an intentional no-op (see definition.ts) —
  // then goes to the graveyard (no alternate cost paid, so no thenExile).
  pilotResolveTop(pilot);

  const result =
    "Auron's Inspiration is cast from hand and resolves for real ({2}{W} paid), then goes to the graveyard; its own +2/+0-to-attackers effect is an intentional no-op in this model (no attacking-creature state tracked).";
  return finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast from hand -> resolve -> graveyard', result);
}

function flashbackCast(): TraceResult {
  const flashback = auronSInspiration.alternateCosts!.find((c) => c.name === 'Flashback')!;
  const setup: EnginePilotSetup = { you: { basicLands: basicLandsFor(flashback.cost) } };
  const pilot = setupEnginePilot(setup);
  // Starts in the graveyard, not hand — a real prior discard/mill/whatever
  // put it there; this scenario is about the flashback cast itself, not how
  // it got to the graveyard.
  const cardReal = pilot.state.addCard(pilot.you, 'Graveyard', { name: auronSInspiration.name, types: [] });
  const actions = pilotActions(pilot, cardReal.id);
  const ctx = pilot.ctxFor(cardReal);

  // Cast via Flashback ({2}{W}{W} from the graveyard), real mana payment
  pilotCast(pilot, cardReal, auronSInspiration, ctx, actions, undefined, flashback);
  // Resolves — its own effect is an intentional no-op (see definition.ts) —
  // then exiled instead of returning to the graveyard (thenExile, CR 702.32).
  pilotResolveTop(pilot);

  const result =
    "Auron's Inspiration is cast from the graveyard via Flashback ({2}{W}{W} paid instead of {2}{W}) and resolves for real, then is exiled instead of returning to the graveyard (its own \"Then exile it\" clause); its own +2/+0-to-attackers effect is again an intentional no-op in this model.";
  return finishEnginePilotTrace(pilot, setup, 'real engine playthrough: Flashback cast from graveyard -> resolve -> exile', result);
}

export function runEngineScenarios(): TraceResult[] {
  return [normalCast(), flashbackCast()];
}

