import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';
import { TOKENS } from '../../tokens.ts';

export const darkKnightsGreatsword: CardDefinition = {
  name: "Dark Knight's Greatsword",
  manaCost: '{2}{B}',
  typeLine: 'Artifact — Equipment',

  staticAbilities: ['Equipped creature gets +3/+0 and is a Knight in addition to its other types.'],

  // Job select — same real ETB mechanic (create a Hero token, attach this
  // to it) as dragoon-s-lance/paladin-s-arms/machinist-s-arsenal/black-
  // mage-s-rod's own onEnter trigger.
  triggers: [
    {
      name: 'onEnter',
      effects: [
        {
          kind: 'custom',
          describe: 'create a 1/1 colorless Hero creature token, then attach this to it',
          run: (ctx: EffectContext, actions: Actions) => {
            const [created] = actions.createToken(ctx.you, TOKENS.c_1_1_hero, 1);
            if (created) actions.equip(ctx.self, created);
          },
        } satisfies Effect,
      ],
    },
  ],

  // Chaosbringer — Equip—Pay 3 life. Activate only once each turn. A
  // non-mana cost (real `K:Equip:PayLife<3>`), same "cost text on
  // activationCost" convention sidequest-catch-a-fish-cooking-campsite's
  // own sacrifice-cost activated ability uses. The life payment is modeled
  // as the FIRST effect below so the trace shows it happening, same
  // convention ahriman/phantom-train's own cost-effects use — "activate
  // only once each turn" has no per-turn-activation-limit tracking
  // anywhere in this model (no turn-structure state at all — same boundary
  // this batch's other turn-based restrictions hit), kept as real text via
  // `activationCost` only.
  activationCost: 'Equip—Pay 3 life (activate only once each turn)',
  effects: [
    { kind: 'loseLife', owner: 'you', amount: 3 } satisfies Effect,
    {
      kind: 'custom',
      describe: 'attach to target creature you control',
      run: (ctx: EffectContext, actions: Actions) => {
        const target = actions.chooseTarget(ctx.you.getCreaturesInPlay());
        if (target) actions.equip(ctx.self, target);
      },
    } satisfies Effect,
  ],
};

deadly-embrace.source:
import type { CardDefinition, Effect, EffectContext } from '../../card';

// Real script (deadly_embrace.txt): "Destroy target creature an opponent
// controls. Then draw a card for each creature that died this turn" — the
// destroy is plain declarative `destroy` (owner: 'opponents' for the real
// `ValidTgts$ Creature.OppCtrl` restriction, same fix `dealDamageTarget`'s
// own doc comment already documents). The real `SVar:X:Count$
// ThisTurnEntered_Graveyard_from_Battlefield_Creature` has no equivalent
// anywhere in this model — no per-turn event history is tracked at all
// (state.ts's own header rules out anything beyond real zone/counter/
// control mutation). Approximated instead as the creature-card count
// across EVERY graveyard at the moment this second effect reads it — since
// effects resolve in order, that count already includes the creature this
// same spell just destroyed (matching Forge's real SubAbility ordering),
// plus whatever a scenario's own `graveyardCreatureCount` seeds as
// "already died" for test purposes (a fresh scenario has no prior turn to
// distinguish from "this turn" anyway) — same "count now, not literally
// this-turn" approximation summon-esper-ramuh's/cloud-of-darkness's own
// graveyard-count `Computed` functions already use for an identical
// per-turn-history gap.
export const deadlyEmbrace: CardDefinition = {
  name: 'Deadly Embrace',
  manaCost: '{3}{B}{B}',
  typeLine: 'Sorcery',

  effects: [
    { kind: 'destroy', validType: 'creature', owner: 'opponents', qty: 1 } satisfies Effect,
    {
      kind: 'drawCard',
      amount: (ctx: EffectContext) => [...ctx.you.getCardsIn('Graveyard'), ...ctx.opponents.flatMap((p) => p.getCardsIn('Graveyard'))].filter((c) => c.isCreature()).length,
    } satisfies Effect,
  ],
};

delivery-moogle.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const deliveryMoogle: CardDefinition = {
  name: 'Delivery Moogle',
  manaCost: '{3}{W}',
  typeLine: 'Creature — Moogle',

  keywords: ['Flying'],

  triggers: [
    {
      name: 'onEnter',
      on: 'enter',
      effects: [
        {
          // "Search your library and/or graveyard for an artifact card with
          // mana value 2 or less" — a genuine two-zone search (real Forge
          // Origin$ Library | OriginAlternative$ Graveyard), which the
          // declarative `move` kind can't express (`from` is exactly one
          // zone). Modeled fully via `custom` instead of narrowing to
          // Library-only, since both zone reads are already real
          // primitives (`getCardsIn`) this model has everywhere else.
          //
          // 2026-09-11 correction: an earlier version of this comment
          // claimed mana value couldn't be filtered here at all ("not
          // tracked anywhere on Card/RealCard") — checked again against
          // interfaces.ts/state.ts/harness.ts while migrating this card's
          // synergy facts and that claim was simply WRONG, not a real
          // engine gap: `Card.getCMC()` is a real, cited interface method
          // (interfaces.ts ~line 106, Card.java ~line 7227), backed by a
          // real `RealCard.getCMC` (state.ts) and already wired into
          // `harness.ts`'s own `loggingCard` wrap (`read:getCMC` trace
          // evidence) — the exact same "real primitive already exists
          // elsewhere in this model" situation `isArtifact` was already in
          // above. The stale claim's own citation ("same real gap
          // cloud-midgar-mercenary's own comment already flags") also
          // doesn't exist — grepped that file, it has no mana-value
          // filter or comment about one at all (Cloud's own search has no
          // mv restriction to begin with). Fixed for real below rather
          // than left as a documented-but-false gap. "Shuffle" has no
          // library-reorder consequence anything downstream reads, so it's
          // not modeled (state.ts's own header rules out anything beyond
          // the action vocabulary card.ts/harness.ts actually use).
          //
          // The graveyard branch is independently exercised by its own
          // scenario (2026-09-11) via `harness.ts`'s new
          // `PlayerState.graveyardArtifactCount` (mirrors the pre-existing
          // `libraryArtifactCount`) — this was a real, fixable harness gap
          // (a missing setup field), not a permanent engine limitation.
          // Neither seeded filler artifact (library or graveyard) is given
          // an explicit `cmc` (defaults to `RealCard.cmc ?? 0`, i.e. 0),
          // so no scenario here currently proves the mv-2-or-less filter
          // actually EXCLUDES a real >2-mv candidate — both real scenarios
          // only demonstrate it correctly ADMITTING a 0-mv one. A future
          // scenario wanting that negative case would need a
          // `libraryArtifactCmc`/`graveyardArtifactCmc`-style harness field
          // this task didn't need to add.
          kind: 'custom',
          describe: 'search your library and/or graveyard for an artifact card with mana value 2 or less and put it into your hand',
          run: (ctx: EffectContext, actions: Actions) => {
            const pool = [...ctx.you.getCardsIn('Library'), ...ctx.you.getCardsIn('Graveyard')].filter((c) => c.isArtifact() && c.getCMC() <= 2);
            if (pool.length === 0) return;
            const target = actions.chooseTarget(pool);
            actions.moveTo(target, 'Hand');
          },
        } satisfies Effect,
      ],
    },
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header). onEnter is a
// real recognized auto-fire (603.6b) — wired via `on: 'enter'` on this
// card's own definition.ts (same convention Cloud, Midgar Mercenary's own
// onEnter uses). Two separate real playthroughs, one per real origin zone
// the card's own "and/or" search actually offers (CR-legal: the ability
// searches BOTH zones and this player may take a card from either) — a
// single trace can only show ONE zone actually yielding the found card
// (the effect's own `pool` always prefers Library first when both zones
// have a hit, see definition.ts), so the Graveyard half needs its own,
// library-empty playthrough to genuinely demonstrate the graveyard branch
// running as real code, not asserted.
//
// Real bug found+fixed while building this scenario (2026-09-11): an
// `EnginePilotSetup` with NO `opponents` produces a genuinely 1-player
// `GameState` (`setupEnginePilot`'s own `[you, ...opponents]` with
// `opponents=[]`). `turn.ts`'s own `shouldSkipDraw` correctly requires
// `playerCount === 2` for CR 103.8a's "skip the starting player's first
// draw" rule (that rule is specifically a 2-PLAYER-game rule, not a
// universal one) — so a 1-player pilot is NOT a real 2-player game and
// legitimately does NOT skip the turn-1 draw, silently pulling a real card
// off the top of `you`'s library during `setupEnginePilot` itself, before
// any scenario code runs. `setupPlayer` adds `libraryArtifactCount`'s own
// artifact card FIRST (library index 0 = "top"), so an early version of
// this scenario (no `opponents`, same shape Cloud, Midgar Mercenary's own
// `scenarios.ts` also uses) had its OWN seeded library artifact silently
// drawn into hand before Delivery Moogle's ETB ever ran — the final hand
// still happened to contain the artifact, so the scenario's own `result`
// string still read as "true," but for the WRONG reason (an incidental
// opening draw, not the card's own tutor effect), and the real trace log
// correctly showed zero `read:isArtifact`/`moveTo` evidence for it. Fixed
// by giving both playthroughs below a real second player (`opponents`),
// restoring a genuine 2-player game so `shouldSkipDraw` applies as
// intended and the seeded artifact survives to be found by the real ETB.
// NOT fixed here (flagged instead, out of scope for a single-card
// migration, reported to the parent session): checked Cloud, Midgar
// Mercenary's OWN checked-in scenario the same way (a scratch script
// replaying its exact `setupEnginePilot` call) and confirmed it has this
// EXACT bug live today, not just a theoretical risk — its own seeded
// library artifact is ALREADY sitting in `you`'s hand immediately after
// `setupEnginePilot` returns, before its own `pilotCast` is even called.
// Its own real ETB `move` effect then runs against an artifact-less
// library (7 plain lands only) and finds nothing — `harness.ts`'s
// declarative `move` action (`move: (player, from, to, qty, validType) =>
// {...}`, used by this `kind:'move'`/dig-style effect, not this card's own
// `custom` one) logs `fn:'move', ..., qty:1, validType:'artifact'`
// UNCONDITIONALLY even though its own `chosen` array is empty — so
// Cloud's checked-in trace.json's apparent "successful tutor" is
// fabricated by the log, not real: the artifact ends up in Cloud's hand
// SOLELY because of the incidental early draw, not because of Cloud's own
// ETB at all. Same root cause (`shouldSkipDraw`'s correct 2-player-only
// gate + a 1-player pilot setup) as this card's own bug, plus a second,
// independent bug (`move`'s unconditional log) this card's own `custom`
// effect never triggers (it already guards `if (pool.length === 0)
// return;` before ever calling `actions.moveTo`, so it can't silently
// claim success on an empty pool the way the shared `move` action can).
// Real fix for Cloud (and any other `kind:'move'`-based tutor scenario
// with no `opponents`) is the same one applied here (add a real second
// player) plus a `harness.ts` fix to only log `fn:'move'` when `chosen`
// is non-empty — both left for a dedicated follow-up since fixing the
// shared `move` helper could change which currently-passing pool cards'
// verify-synergy evidence check still passes, which needs its own
// full-pool audit, not a change bundled into this card's migration.

import { deliveryMoogle } from './definition';
import { basicLandsFor } from '../../mana';
import type { TraceResult } from '../../harness';
import { setupEnginePilot, pilotActions, pilotCast, pilotResolveTop, finishEnginePilotTrace, type EnginePilotSetup } from '../../engine-trace';

export function runEngineScenarios(): TraceResult[] {
  const librarySetup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{3}{W}'), libraryCount: 3, libraryArtifactCount: 1 },
    opponents: [{ basicLands: ['Forest'], libraryCount: 5 }],
  };
  const libraryPilot = setupEnginePilot(librarySetup);
  const libraryMoogle = libraryPilot.state.addCard(libraryPilot.you, 'Hand', { name: deliveryMoogle.name, types: ['Creature'], subtypes: ['Moogle'] });
  const libraryActions = pilotActions(libraryPilot, libraryMoogle.id);
  const libraryCtx = libraryPilot.ctxFor(libraryMoogle);

  // Cast Delivery Moogle ({3}{W}), real mana payment
  pilotCast(libraryPilot, libraryMoogle, deliveryMoogle, libraryCtx, libraryActions);
  // Resolves; real 603.6b ETB auto-fires — searches the real library (mana
  // value 2 or less, real `getCMC()` check) for the one real artifact card,
  // puts it into hand
  pilotResolveTop(libraryPilot);

  const libraryResult =
    'Delivery Moogle enters; real ETB (603.6b) searches your real library for an artifact card with mana value 2 or less (real getCMC() check), puts it into hand.';
  const libraryTrace = finishEnginePilotTrace(
    libraryPilot,
    librarySetup,
    'real engine playthrough: cast -> real ETB library search',
    libraryResult,
  );

  const graveyardSetup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{3}{W}'), libraryCount: 3, graveyardArtifactCount: 1 },
    opponents: [{ basicLands: ['Forest'], libraryCount: 5 }],
  };
  const graveyardPilot = setupEnginePilot(graveyardSetup);
  const graveyardMoogle = graveyardPilot.state.addCard(graveyardPilot.you, 'Hand', { name: deliveryMoogle.name, types: ['Creature'], subtypes: ['Moogle'] });
  const graveyardActions = pilotActions(graveyardPilot, graveyardMoogle.id);
  const graveyardCtx = graveyardPilot.ctxFor(graveyardMoogle);

  // Cast Delivery Moogle again in a SEPARATE playthrough with no library
  // artifact at all, so the real ETB's own `pool` (Library first, then
  // Graveyard — see definition.ts) has nothing to find in Library and
  // genuinely falls through to the Graveyard candidate this setup seeds.
  pilotCast(graveyardPilot, graveyardMoogle, deliveryMoogle, graveyardCtx, graveyardActions);
  pilotResolveTop(graveyardPilot);

  const graveyardResult =
    "Delivery Moogle enters with no artifact in library; real ETB (603.6b) falls through to the real artifact card sitting in your graveyard (mana value 2 or less, real getCMC() check), puts it into hand.";
  const graveyardTrace = finishEnginePilotTrace(
    graveyardPilot,
    graveyardSetup,
    'real engine playthrough: cast -> real ETB graveyard search',
    graveyardResult,
  );

  return [libraryTrace, graveyardTrace];
}

