import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';
import { TOKENS } from '../../tokens.ts';

// A transforming DFC Legendary Creature // Saga — same shape as jecht-
// reluctant-guardian-braska-s-final-aeon (front-face damage trigger reused
// here as the {4}{W}{W}, {T} exile-then-return activated ability instead;
// backFace's own Saga chapters become named triggers, same 714.3a/b
// simplification documented there).
export const dionBahamutsDominant: CardDefinition = {
  name: "Dion, Bahamut's Dominant",
  manaCost: '{3}{W}',
  typeLine: 'Legendary Creature — Human Noble Knight',
  pt: [3, 3],

  // "Dragonfire Dive — During your turn, Dion and other Knights you
  // control have flying" — real, QUERY-TIME continuous keyword grant
  // (ENGINE_GAPS.md gap #14, closed 2026-09-12): `state.ts`'s own
  // `effectiveKeywords` re-evaluates this live off `state.activePlayerId`
  // every time Dion's (or a Knight's) keywords are read, so it genuinely
  // turns on/off as turns pass in a real engine-piloted playthrough —
  // `includeSelf: true` (Dion himself), `subtype: 'Knight'` (every OTHER
  // Knight you control), `onlyDuringYourTurn: true`.
  continuousKeywordGrants: [{ keywords: ['Flying'], includeSelf: true, subtype: 'Knight', onlyDuringYourTurn: true }],

  triggers: [
    {
      name: 'onEnter',
      // Real 603.6b "enters the battlefield" trigger — `on: 'enter'` wires
      // this to `engine.ts`'s own real auto-fire on `resolveTop` (same
      // convention Jill, Shiva's Dominant/Cloud, Midgar Mercenary's own
      // onEnter both use), needed for the real engine-piloted scenario
      // below (2026-09-11 consolidation) to demonstrate this token ETB for
      // real rather than a scenario naming the trigger explicitly.
      on: 'enter',
      effects: [{ kind: 'createToken', token: TOKENS.w_2_2_knight, amount: 1 } satisfies Effect],
    },
  ],

  activationCost: '{4}{W}{W}, {T}',
  effects: [
    {
      kind: 'custom',
      describe: "exile Dion, then return it to the battlefield transformed under its owner's control (activate only as a sorcery)",
      run: (ctx: EffectContext, actions: Actions) => {
        actions.moveTo(ctx.self, 'Exile');
        actions.moveTo(ctx.self, 'Battlefield');
      },
    } satisfies Effect,
  ],

  backFace: {
    name: 'Bahamut, Warden of Light',
    manaCost: '',
    typeLine: 'Legendary Enchantment Creature — Saga Dragon',
    pt: [5, 5],
    keywords: ['Flying'],
    triggers: [
      {
        name: 'chapterI',
        effects: [
          {
            // "Put a +1/+1 counter on each OTHER creature you control"
            // (StrictlyOther) is a board-wide broadcast excluding self —
            // `putCounter` is self-only, `putCounterTarget` is a CHOSEN
            // pool, and `pumpAll` (the closest board-wide shape) has no
            // notSelf exclusion either.
            kind: 'custom',
            describe: 'Wings of Light — put a +1/+1 counter on each other creature you control',
            run: (ctx: EffectContext, actions: Actions) => {
              for (const creature of ctx.you.getCreaturesInPlay().filter((c) => c.getId() !== ctx.self.getId())) actions.putCounter(creature, '+1/+1', 1);
            },
          } satisfies Effect,
          {
            // "Those creatures gain flying until end of turn" — the SAME
            // "each other creature you control" pool as the counters above,
            // now real and executable via `grantKeywordAll` (card.ts,
            // added 2026-09-09 — genuinely wasn't available when the
            // comment this replaces was first written). `notSelf: true`
            // matches the counters effect's own `.filter` exclusion.
            // Duration ("until end of turn") isn't tracked — same
            // documented `layers.ts`/`state.grantKeyword` simplification
            // every other keyword grant in this pool already accepts (the
            // grant persists for the rest of the scenario, not just until
            // end of turn).
            kind: 'grantKeywordAll',
            predicate: 'creatures-you-control',
            keyword: 'Flying',
            notSelf: true,
          } satisfies Effect,
        ],
      },
      {
        name: 'chapterII',
        effects: [
          {
            kind: 'custom',
            describe: 'Wings of Light — put a +1/+1 counter on each other creature you control',
            run: (ctx: EffectContext, actions: Actions) => {
              for (const creature of ctx.you.getCreaturesInPlay().filter((c) => c.getId() !== ctx.self.getId())) actions.putCounter(creature, '+1/+1', 1);
            },
          } satisfies Effect,
          {
            kind: 'grantKeywordAll',
            predicate: 'creatures-you-control',
            keyword: 'Flying',
            notSelf: true,
          } satisfies Effect,
        ],
      },
      {
        name: 'chapterIII',
        effects: [
          // Real script (dion_bahamuts_dominant_bahamut_warden_of_light.txt,
          // ALTERNATE face): `SVar:DBGigaflare:DB$ Destroy | ValidTgts$
          // Permanent` — no controller restriction ("destroy target
          // permanent," not "target permanent an opponent controls"), so no
          // `owner` field belongs here (an `owner: 'opponents'` restriction
          // would misrepresent the real, unrestricted card). See
          // scenarios.ts's own comment on the resulting self-destroy.
          { kind: 'destroy', validType: 'permanent', qty: 1 } satisfies Effect,
          {
            // "Exile Bahamut, then return it to the battlefield (front face
            // up)" — same exile/return simplification the front face's own
            // transform ability uses (this model has no notion of "which
            // face is showing" as tracked state beyond `backFace` being a
            // second static CardDefinition), just without the `Transformed$`
            // flag real Forge sets.
            kind: 'custom',
            describe: 'Gigaflare — exile Bahamut, then return it to the battlefield (front face up)',
            run: (ctx: EffectContext, actions: Actions) => {
              actions.moveTo(ctx.self, 'Exile');
              actions.moveTo(ctx.self, 'Battlefield');
            },
          } satisfies Effect,
        ],
      },
    ],
  },
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header) — this
// card's transforming-DFC-into-a-Saga arc played out for real, one
// continuous playthrough, same real shape jill-shiva-s-dominant-shiva-
// warden-of-ice's own scenarios.ts already established (2026-09-11
// consolidation, user's own live call: "let's make 1 scenario, not 5" —
// replaces the old 5 separate flat harness.ts scenarios, one per named
// trigger/chapter, each of which skipped straight to "already on the
// battlefield" and never demonstrated a real cast or real turn passage at
// all).

import { dionBahamutsDominant } from './definition';
import { basicLandsFor } from '../../mana';
import { typesFromTypeLine, subtypesFromTypeLine } from '../../harness';
import { effectiveKeywords } from '../../state';
import type { TraceResult } from '../../harness';
import {
  setupEnginePilot,
  pilotActions,
  pilotCast,
  pilotResolveTop,
  advanceToPlayersNextMain1,
  pilotActivate,
  pilotTransform,
  finishEnginePilotTrace,
  type EnginePilotSetup,
} from '../../engine-trace';

export function runEngineScenarios(): TraceResult[] {
  // Real Coeurl on the opponent's side — a real, demonstrated target for
  // Gigaflare's own "Destroy target permanent" later (real script:
  // ValidTgts$ Permanent, no owner restriction). Also replaces the old flat
  // scenario's own documented self-destroy modeling-limitation finding
  // (chooseTarget's own first-pool-candidate rule always picked Dion/
  // Bahamut itself when nothing forced otherwise) with a real, explicit
  // `preferTarget` choice instead, same technique jill-shiva-s-dominant's
  // own ETB bounce target uses.
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{4}{W}{W}'), libraryCount: 15 },
    opponents: [{ basicLands: ['Forest'], libraryCount: 10 }],
  };
  const pilot = setupEnginePilot(setup);

  const oppCreature = pilot.state.addCard(pilot.opponents[0]!, 'Battlefield', {
    name: 'Coeurl',
    types: ['Creature'],
    subtypes: ['Cat', 'Beast'],
    basePower: 2,
    baseToughness: 2,
    cmc: 2,
  });
  pilot.log.push({ fn: 'enters', card: oppCreature.name, zone: 'Battlefield', power: oppCreature.basePower, toughness: oppCreature.baseToughness, controller: pilot.opponents[0]!.name });

  const dionReal = pilot.state.addCard(pilot.you, 'Hand', {
    name: dionBahamutsDominant.name,
    types: typesFromTypeLine(dionBahamutsDominant.typeLine),
    subtypes: subtypesFromTypeLine(dionBahamutsDominant.typeLine),
    basePower: dionBahamutsDominant.pt?.[0],
    baseToughness: dionBahamutsDominant.pt?.[1],
  });
  const actions = pilotActions(pilot, dionReal.id);

  // Cast Dion from hand (601), real {3}{W} mana payment
  pilotCast(pilot, dionReal, dionBahamutsDominant, pilot.ctxFor(dionReal), actions);
  // Resolves; real ETB (603.6b) creates a 2/2 white Knight creature token
  pilotResolveTop(pilot);

  // Real, deliberate query against the real board state — Dragonfire Dive's
  // own front-face grant (`continuousKeywordGrants`, ENGINE_GAPS.md gap #14)
  // is QUERY-TIME, not a discrete action, so no `fn:'grantKeyword'` line
  // could ever prove it fired; this asks the exact same real function
  // `hasKeyword` itself consults (`state.ts`'s own `effectiveKeywords`),
  // same "manual CDA read" pattern adelbert-steiner's own `read:getNetPower`
  // line already establishes. It's genuinely your own turn right now (turn
  // 1, right after Dion resolves), so this is real, true evidence, not
  // fabricated.
  pilot.beginStep("Real query: Dragonfire Dive's own grant, during your turn");
  pilot.log.push({ fn: 'read:hasKeyword', target: dionReal.name, keyword: 'Flying', result: effectiveKeywords(pilot.state, dionReal).includes('Flying') });

  // Real turn passage — summoning sickness (302.6) clears
  advanceToPlayersNextMain1(pilot, pilot.you);

  // Activate the transform (602.1: {4}{W}{W}, {T}, sorcery speed)
  pilotActivate(pilot, pilot.you, dionReal, dionBahamutsDominant, pilot.ctxFor(dionReal), actions);
  pilotResolveTop(pilot);

  // Front -> Bahamut, Warden of Light. Real 714.2b/c: enters as a Saga with
  // no lore counters, then immediately gets its first — chapter I fires
  // here (Wings of Light: +1/+1 counter and flying on the Knight token,
  // the real "other creature you control").
  const backFace = dionBahamutsDominant.backFace!;
  const bahamutCtx = pilot.ctxFor(dionReal);
  pilotTransform(pilot, dionReal, backFace, bahamutCtx, actions);

  // Real turn passage through your next draw step — chapter II fires for
  // real (Wings of Light again)
  advanceToPlayersNextMain1(pilot, pilot.you, dionReal);

  // Gigaflare's own real target, set on the SAME ctx object saga.ts's own
  // automatic tick below reuses (EnginePilotCtxOpts's own doc comment:
  // mutating a previously-returned ctx before a LATER automatic trigger
  // fire is how a pilot script feeds it a value an earlier call didn't
  // need yet) — the opponent's real Coeurl, not Bahamut itself.
  bahamutCtx.preferTarget = (c) => c.getName() === 'Coeurl';

  // Another real turn — chapter III fires: destroys the opponent's Coeurl
  // (Gigaflare), then exiles Bahamut and returns it transformed back to
  // Dion
  advanceToPlayersNextMain1(pilot, pilot.you, dionReal);

  // Re-register the front face after the transform-back (saga.ts's own
  // convention: a piloting caller must call this explicitly)
  pilotTransform(pilot, dionReal, dionBahamutsDominant, pilot.ctxFor(dionReal), actions);

  const result =
    "Dion enters; real ETB (603.6b) creates a 2/2 white Knight token. Once summoning sickness clears, {4}{W}{W}, {T} exiles Dion and returns it transformed as Bahamut, Warden of Light — real 714.2b/c, chapter I fires immediately (Wings of Light: +1/+1 counter and flying on the Knight token). Chapter II fires on your next draw step (Wings of Light again). Chapter III fires the turn after (Gigaflare: destroys the opponent's real Coeurl, then exiles Bahamut and returns it as Dion) — all through the real turn-based engine.";

  return [finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast -> ETB -> transform -> Saga chapters over real turns', result)];
}

doppelgang.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const doppelgang: CardDefinition = {
  name: 'Doppelgang',
  manaCost: '{X}{X}{X}{G}{U}',
  typeLine: 'Sorcery',

  effects: [
    {
      // "For each of X target permanents, create X tokens that are copies
      // of that permanent." No declarative shape for "target N permanents,
      // then copy each N times" — custom, using the real injectable
      // `copyPermanent` action (one copy per call, so X targets * X
      // copies each = a nested loop).
      kind: 'custom',
      describe: 'for each of X target permanents, create X tokens that are copies of that permanent',
      run: (ctx: EffectContext, actions: Actions) => {
        const x = ctx.xPaid ?? 0;
        const pool = [ctx.you, ...ctx.opponents].flatMap((p) => p.getCardsIn('Battlefield'));
        const targets = [];
        for (let i = 0; i < x; i++) {
          const remaining = pool.filter((c) => !targets.includes(c));
          if (remaining.length === 0) break;
          targets.push(actions.chooseTarget(remaining));
        }
        for (const target of targets) {
          for (let i = 0; i < x; i++) actions.copyPermanent(target, ctx.you);
        }
      },
    } satisfies Effect,
  ],
};

