elixir.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

// Real script (elixir.txt): "This artifact enters tapped" — a real
// replacement effect, modeled as an onEnter trigger tapping self, same
// pool-based `tapTarget` convention shambling-cie-th/stuck-in-summoners-
// sanctum's own onEnter triggers already use (self is genuinely already on
// the battlefield by the time a named trigger's effects run — see
// harness.ts's own selfZone rule — so `owner: 'you'` finds exactly self as
// long as the scenario sets up no other artifact for "you").
//
// "{5}, {T}, Exile this artifact: Shuffle all nonland cards from your
// graveyard into your library. You gain life equal to the number of cards
// shuffled into your library this way." The {T}/Exile-self are COSTS, kept
// as `activationCost` text only (same convention phoenix-down's own
// "{1}{W}, {T}, Exile this artifact" cost uses). The effect itself needs a
// `custom`: `move`'s own validType has no "nonland" filter (only
// 'creature'|'artifact'|'land'|'any' — same gap white-auracite's own
// comment already flags for its own "nonland permanent" target), AND the
// life gained depends on how many cards actually moved — a runtime count
// no declarative `gainLife` amount can read back from a prior `move`
// effect in the same list. Both real primitives (`moveTo`, `you.gainLife`)
// exist and are used directly, so this is a precise custom implementation,
// not an invented mechanic.
export const elixir: CardDefinition = {
  name: 'Elixir',
  manaCost: '{1}',
  typeLine: 'Artifact',

  triggers: [
    {
      name: 'onEnter',
      effects: [{ kind: 'tapTarget', validType: 'artifact', owner: 'you' } satisfies Effect],
    },
  ],

  activationCost: '{5}, {T}, Exile this artifact',
  effects: [
    {
      kind: 'custom',
      describe: 'shuffle all nonland cards from your graveyard into your library; you gain life equal to the number of cards shuffled this way',
      run: (ctx: EffectContext, actions: Actions) => {
        const nonland = ctx.you.getCardsIn('Graveyard').filter((c) => !c.isLand());
        for (const card of nonland) actions.moveTo(card, 'Library');
        if (nonland.length > 0) ctx.you.gainLife(nonland.length);
      },
    } satisfies Effect,
  ],
};

elrond-moon-reader.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const elrondMoonReader: CardDefinition = {
  name: 'Elrond, Moon-Reader',
  manaCost: '{2}{U}',
  typeLine: 'Legendary Creature — Elf Noble',
  pt: [3, 3],

  triggers: [
    {
      // Real "Whenever you activate an ability of a creature, draw a card.
      // This ability triggers only once each turn." — the once-per-turn
      // cap has no representable state here (no per-turn trigger-count
      // tracking anywhere in this model), so a scenario just exercises one
      // activation -> one draw; a real game's second activation in the
      // same turn wouldn't draw again, this model would.
      name: 'onActivateCreatureAbility',
      effects: [{ kind: 'drawCard', amount: 1 } satisfies Effect],
    },
  ],

  activationCost: '{5}{U}{U}',
  effects: [
    {
      // Real "Exile up to two other target nonland permanents you control.
      // Return those cards to the battlefield under their owner's control
      // at the beginning of the next end step." `move`'s own `validType`
      // vocabulary ('creature'|'artifact'|'land'|'any') has no "nonland"
      // shape, so a declarative `move` can't express this filter — custom,
      // reading `isLand()` directly, is the honest shape. The "next end
      // step" delay IS a real delayed trigger now (`actions.delayUntil`,
      // functional-model/state.ts's `scheduleDelayedTrigger` +
      // functional-model/turn.ts's phase-entry drain) — the return
      // genuinely doesn't run until the game reaches EndOfTurn, proved by
      // this card's own `advanceToPhase: 'EndOfTurn'` scenario.
      kind: 'custom',
      describe: 'exile up to two other target nonland permanents you control, then return them to the battlefield under their owner\'s control at the beginning of the next end step',
      run: (ctx: EffectContext, actions: Actions) => {
        const pool = ctx.you.getCardsIn('Battlefield').filter((c) => !c.isLand() && c.getId() !== ctx.self.getId());
        const targets = [];
        for (let i = 0; i < 2; i++) {
          const remaining = pool.filter((c) => !targets.includes(c));
          if (remaining.length === 0) break;
          targets.push(actions.chooseTarget(remaining));
        }
        // Exile BOTH targets now — matches the real card's own two-step
        // structure (a single "exile up to two" event now, then a single
        // LATER "return those cards" event acting on the whole batch), not
        // two independent exile-then-immediately-return pairs.
        for (const t of targets) actions.moveTo(t, 'Exile');
        // Real rule: an exiled TOKEN ceases to exist and never comes back
        // (no other-zone printed existence) — not modeled here (this
        // model has no existence-check a card author can call without an
        // extra zone read that would need its own declared want), so a
        // token target would incorrectly "return." Scenarios below only
        // target nontoken permanents, so this never actually fires.
        actions.delayUntil('EndOfTurn', () => {
          for (const t of targets) actions.moveTo(t, 'Battlefield');
        });
      },
    } satisfies Effect,
  ],
};

elven-passage.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const elvenPassage: CardDefinition = {
  name: 'Elven Passage',
  manaCost: '',
  typeLine: 'Land',

  activationCost: '{T}, Pay 1 life, Sacrifice this land',
  effects: [
    { kind: 'loseLife', owner: 'you', amount: 1 } satisfies Effect,
    {
      // Real "Search your library for a basic land card, put it onto the
      // battlefield tapped, then shuffle. You may behold an Elf. If you
      // do, untap that land." Self-sacrifice (part of the activation
      // cost) plus a full-library search-to-battlefield have no
      // declarative shape (`sacrifice`'s own chooseTarget could pick a
      // DIFFERENT land than self; `dig`/`move` only reach hand/graveyard,
      // never battlefield) — custom, moving `ctx.self` directly and
      // reading the whole library. "Basic" isn't checked (no
      // supertype/hasSupertype anywhere in this model, only `isLand()`) —
      // matches any land, not just a basic one. The "behold an Elf" choice
      // (untap if you do) isn't modeled at all — no engine concept of
      // "reveal a card from hand" or a player's own free choice exists
      // here (chooseTarget is always deterministic) — the fetched land
      // simply stays tapped.
      kind: 'custom',
      describe: 'sacrifice this land, then search your library for a basic land card and put it onto the battlefield tapped (behold-an-Elf untap choice not modeled)',
      run: (ctx: EffectContext, actions: Actions) => {
        actions.moveTo(ctx.self, 'Graveyard');
        const [land] = ctx.you.getCardsIn('Library').filter((c) => c.isLand());
        if (land) {
          actions.moveTo(land, 'Battlefield');
          actions.tap(land);
        }
      },
    } satisfies Effect,
  ],
};

