fang-fearless-l-cie.source:
import type { CardDefinition, Effect } from '../../card';

// Real script (fang_fearless_lcie.txt): `AlternateMode:Meld`,
// `MeldPair:Vanille, Cheerful l'Cie` — Fang MELDS with a separate card
// (Vanille, Cheerful l'Cie, not in this batch) into a THIRD card, Ragnarok,
// Divine Deliverance. Confirmed via both the Forge script and Scryfall (its
// own `all_parts` lists Fang as `meld_part`, Ragnarok as `meld_result`,
// alongside Vanille as the other `meld_part` — a real 3-card group, not a
// 2-card transforming DFC pair).
//
// This is NOT what `CardDefinition.backFace` models: `backFace` is
// documented (and every existing user — Jecht/Braska's Final Aeon, Dion/
// Bahamut — confirms this) as ONE object transforming into its own second
// face, reached via that SAME object's own ability (`ChangeZone` exile-then-
// return). Meld is mechanically different — TWO separate permanents (each
// independently cast, independently a real object with its own zone
// history) are exiled together and replaced by a THIRD, new object; neither
// original card "is" the melded result the way a DFC's back face "is" the
// same permanent. Authoring Ragnarok as Fang's own `backFace` would
// misrepresent it as reachable by Fang's own ability alone, when the real
// trigger lives on Vanille (a card this batch doesn't include) and requires
// both permanents. No CardDefinition field models "two permanents consume
// into a third" at all — flagged as a real gap in this batch's own final
// report, not worked around.
//
// So: Fang is authored here as its own standalone, real, independently
// castable card (all its own printed text is fully modelable on its own).
// Ragnarok, Divine Deliverance is SKIPPED rather than force-fit as a
// `backFace` that would misrepresent the mechanic.
export const fangFearlessLcie: CardDefinition = {
  name: "Fang, Fearless l'Cie",
  manaCost: '{2}{B}',
  typeLine: 'Legendary Creature — Human Warrior',

  pt: [2, 3],

  triggers: [
    {
      // "This ability triggers only once each turn" — no once-per-turn
      // firing limit is tracked anywhere in this model (a scenario firing
      // a named trigger already stands in for "the real triggering
      // condition was met," same as every other conditional trigger name in
      // this repo — Minwu's own `onLifeGained`, e.g.); the limit itself is
      // real text with no field to enforce it against, same documentary
      // treatment as `ActivationLimit$`-style caps elsewhere in this batch.
      name: 'onGraveyardCardsLeave',
      effects: [{ kind: 'drawCard' } satisfies Effect, { kind: 'loseLife', owner: 'you', amount: 1 } satisfies Effect],
    },
  ],
};

fate-of-the-sun-cryst.source:
import type { CardDefinition, Effect } from '../../card';

export const fateOfTheSunCryst: CardDefinition = {
  name: 'Fate of the Sun-Cryst',
  manaCost: '{4}{W}',
  typeLine: 'Instant',

  // Real Forge S:Mode$ ReduceCost — a genuine dynamic mana-cost reduction
  // keyed on the chosen target's tapped state at cast time. No cost-
  // reduction machinery exists anywhere in this model (`manaCost` is a
  // fixed printed string, never recomputed for a specific cast) — same
  // treatment every other continuous/cost-affecting static ability gets:
  // real text, not an executed effect.
  staticAbilities: ['This spell costs {2} less to cast if it targets a tapped creature.'],

  effects: [{ kind: 'destroy', validType: 'permanent', nonLand: true, qty: 1 } satisfies Effect],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header) — a plain
// instant, one real scenario: cast targeting the opponent's only real
// nonland permanent (no other candidate exists on either battlefield, so
// the unrestricted `destroy` pool resolves to it with no preferTarget
// needed). The card's own "costs {2} less if it targets a tapped creature"
// cost-reduction clause is a real, DOCUMENTED engine gap (ENGINE_GAPS.md
// #7 — cost-reduction effects aren't modeled at all, only Flashback-style
// cost REPLACEMENT is) — not exercised here; this scenario pays the full
// printed {4}{W} and just demonstrates the actual destroy effect.
//
// Target is a real, NON-TOKEN permanent (Coeurl, data/fin/fin_scryfall.json:
// {1}{W} Creature — Cat Beast, 2/2 — same real card summon-bahamut's own
// scenario A uses), not a token: `card.ts`'s `destroy` case logs a literal
// `fn:'destroy'` line only for a real permanent; a token instead logs
// `ceasesToExist` (111.7/704.5d — a token ceases to exist rather than ever
// really sitting in a graveyard), which can't back a real `event:'destroy'`
// ACT fact as trace evidence (same reasoning documented on summon-bahamut's
// own scenario file).

import { fateOfTheSunCryst } from './definition';
import { basicLandsFor } from '../../mana';
import type { TraceResult } from '../../harness';
import { setupEnginePilot, pilotActions, pilotCast, pilotResolveTop, finishEnginePilotTrace, type EnginePilotSetup } from '../../engine-trace';

function destroysOpponentCreature(): TraceResult {
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{4}{W}') },
    opponents: [{}],
  };
  const pilot = setupEnginePilot(setup);

  const oppCreature = pilot.state.addCard(pilot.opponents[0]!, 'Battlefield', { name: 'Coeurl', types: ['Creature'], subtypes: ['Cat', 'Beast'], basePower: 2, baseToughness: 2, cmc: 2 });
  pilot.log.push({ fn: 'enters', card: oppCreature.name, zone: 'Battlefield', power: oppCreature.basePower, toughness: oppCreature.baseToughness, controller: pilot.opponents[0]!.name });

  const cardReal = pilot.state.addCard(pilot.you, 'Hand', { name: fateOfTheSunCryst.name, types: [] });
  const actions = pilotActions(pilot, cardReal.id);
  const ctx = pilot.ctxFor(cardReal);

  pilotCast(pilot, cardReal, fateOfTheSunCryst, ctx, actions);
  pilotResolveTop(pilot);

  const result = "Destroys the opponent's real Coeurl, the only nonland permanent on either battlefield (a real, non-token permanent, so it's a real 701.6 destroy, not a token ceasing to exist); the spell itself then goes to its owner's graveyard after resolving (rule 608.2m).";
  return finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast -> resolve (Destroy target nonland permanent)', result);
}

export function runEngineScenarios(): TraceResult[] {
  return [destroysOpponentCreature()];
}

