from-father-to-son.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const fromFatherToSon: CardDefinition = {
  name: 'From Father to Son',
  manaCost: '{1}{W}',
  typeLine: 'Sorcery',

  alternateCosts: [{ name: 'Flashback', cost: '{4}{W}{W}{W}', from: 'graveyard', thenExile: true }],

  effects: [
    {
      // Destination depends on `castFrom` (Hand -> Hand, graveyard/
      // Flashback -> Battlefield directly) — the declarative `move` kind
      // has one fixed `to`, no branch on how the card itself was cast, so
      // this genuinely needs `custom`'s access to `ctx.castFrom` (the same
      // real, scenario-supplied fact `lifecycleAfter` in harness.ts already
      // reads to decide graveyard-vs-exile for the spell itself).
      //
      // "Vehicle card" — no Vehicle-subtype tracking exists on a generic
      // library card (state.ts's RealCard has a bare `subtypes` string
      // array with no scenario-facing way to populate it for a Library
      // card), so narrowed to `isArtifact()` as the closest honest match —
      // same "Equipment ⊂ Artifact" narrowing cloud-midgar-mercenary's own
      // comment already documents for its own search effect (a Vehicle is
      // always an Artifact too). "Then shuffle" has no observable
      // consequence anything downstream reads, so it's not modeled.
      kind: 'custom',
      describe:
        'search your library for a Vehicle card and put it into your hand, or onto the battlefield instead if this spell was cast from a graveyard; then shuffle',
      run: (ctx: EffectContext, actions: Actions) => {
        const pool = ctx.you.getCardsIn('Library').filter((c) => c.isArtifact());
        if (pool.length === 0) return;
        const target = actions.chooseTarget(pool);
        actions.moveTo(target, ctx.castFrom === 'graveyard' ? 'Battlefield' : 'Hand');
      },
    } satisfies Effect,
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header). 2026-09-12:
// consolidated the old 2 separate scenarios (a plain hand-cast, a separate
// standalone Flashback-cast) into ONE continuous playthrough, per the
// user's own live call: "use only one scenario: first cast from hand -
// fetch one artifact, then cast from graveyard - place on the battlefield."
// Mirrors auron-s-inspiration's own real Flashback pattern (`canCastSpell`/
// `castSpell`/`pilotCast`'s `alt` param, ENGINE_GAPS.md gap #7) — this
// card's own effect genuinely branches on `ctx.castFrom` ("If this spell
// was cast from a graveyard, put that card onto the battlefield instead"),
// which is what originally surfaced the real, narrow `ctxFor` gap fixed in
// `engine-trace.ts` itself (`EnginePilotCtxOpts.castFrom`).

import { fromFatherToSon } from './definition';
import { basicLandsFor } from '../../mana';
import type { TraceResult } from '../../harness';
import { setupEnginePilot, pilotActions, pilotCast, pilotResolveTop, finishEnginePilotTrace, type EnginePilotSetup } from '../../engine-trace';

// Two real, DISTINCT FIN Vehicle printings (data/fin/fin_scryfall.json) —
// the first one leaves the library for real after the hand-cast search, so
// the graveyard/Flashback-cast's own search needs its own real candidate
// still sitting there; reusing the same single card across both searches
// would be dishonest about what's actually happening (it can't be searched
// for twice when the first search already found and moved it).
const REAL_VEHICLE_NAME_1 = 'Magitek Armor'; // Artifact — Vehicle
const REAL_VEHICLE_NAME_2 = 'Cargo Ship'; // Artifact — Vehicle

export function runEngineScenarios(): TraceResult[] {
  const flashback = fromFatherToSon.alternateCosts!.find((c) => c.name === 'Flashback')!;
  // Enough real lands for BOTH real casts within the same turn/main phase
  // without needing an untap step in between ({1}{W} + {4}{W}{W}{W} =
  // {5}{W}{W}{W}{W} combined, no land reused across the two payments) —
  // simpler and just as real as staging a turn passage purely to reuse a
  // smaller land base would have been.
  const setup: EnginePilotSetup = { you: { basicLands: basicLandsFor('{5}{W}{W}{W}{W}'), libraryCount: 3 } };
  const pilot = setupEnginePilot(setup);
  // Appended AFTER `setupEnginePilot` (which itself already advances
  // through one real Draw step during setup — see this file's own earlier
  // header on a single-player board's real CR 103.8a first-draw exposure)
  // so neither real Vehicle is the one silently drawn away before this
  // card's own search ever runs.
  pilot.state.addCard(pilot.you, 'Library', { name: REAL_VEHICLE_NAME_1, types: ['Artifact'] });
  pilot.state.addCard(pilot.you, 'Library', { name: REAL_VEHICLE_NAME_2, types: ['Artifact'] });

  const cardReal = pilot.state.addCard(pilot.you, 'Hand', { name: fromFatherToSon.name, types: [] });
  const actions = pilotActions(pilot, cardReal.id);

  // Cast from hand ({1}{W}), real mana payment — castFrom defaults to 'hand'
  pilotCast(pilot, cardReal, fromFatherToSon, pilot.ctxFor(cardReal), actions);
  // Resolves — real library search finds Magitek Armor and puts it into
  // hand (castFrom is 'hand'), then the spell itself goes to the graveyard
  // for real (CR 608.2m, no alternate cost paid this cast, so no thenExile).
  pilotResolveTop(pilot);

  // Cast AGAIN, this time via Flashback ({4}{W}{W}{W}) straight from the
  // graveyard it just landed in (`cardReal` is the exact same real
  // instance, now real `zone: 'Graveyard'` — no separate card needed).
  const flashbackCtx = pilot.ctxFor(cardReal, { castFrom: 'graveyard' });
  pilotCast(pilot, cardReal, fromFatherToSon, flashbackCtx, actions, undefined, flashback);
  // Resolves — real library search finds the second real Vehicle (Cargo
  // Ship) and puts it directly onto the battlefield this time (castFrom is
  // 'graveyard'), then the spell itself is exiled instead of returning to
  // the graveyard (thenExile, CR 702.32).
  pilotResolveTop(pilot);

  const result =
    'From Father to Son is cast from hand for {1}{W} and resolves for real: searches the real library for a real Vehicle card (Magitek Armor) and puts it into hand, then goes to the graveyard. It is then cast AGAIN from the graveyard via Flashback for {4}{W}{W}{W}: searches the real library for another real Vehicle card (Cargo Ship) and puts it directly onto the battlefield this time (cast from a graveyard), then the spell itself is exiled instead of returning to the graveyard.';
  return [finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast from hand -> search to hand -> graveyard -> Flashback cast -> search to battlefield -> exile', result)];
}

g-raha-tia.source:
import type { CardDefinition, Effect } from '../../card';

export const gRahaTia: CardDefinition = {
  name: "G'raha Tia",
  manaCost: '{4}{W}',
  typeLine: 'Legendary Creature — Cat Archer',

  keywords: ['Reach'],

  // "The Allagan Eye ... triggers only once each turn" — an
  // ActivationLimit real Forge tracks per-turn; no turn-counter/trigger-
  // frequency-limiting state exists anywhere in this model (turn.ts tracks
  // phases/steps, not per-ability activation counts), so this is a real,
  // flagged gap rather than a fabricated once-per-turn guard. A scenario
  // exercises the trigger firing once, which is all `resolveCard()` ever
  // does per call regardless.
  triggers: [
    {
      name: 'onOtherPermanentsDie',
      effects: [{ kind: 'drawCard' } satisfies Effect],
    },
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header) — REPLACES
// the earlier bare `{trigger:'onOtherPermanentsDie'}` flat-scenario shortcut.
// That shape's own `lifecycleBefore`/`lifecycleAfter` (harness.ts) skip the
// cast/enters lifecycle entirely for a `trigger`-shaped scenario ("already on
// the battlefield" — see that function's own doc comment), so it produced no
// real evidence at all for this card's own baseline self-cast/self-enters
// facts. `onDies`-class triggers deliberately never auto-fire anywhere in
// this engine (same real pattern aerith-gainsborough/dwarven-castle-guard
// already establish): the real event has to actually happen first, THEN the
// trigger fires manually to demonstrate its own effect.
//
// Real oracle text: "Reach\nThe Allagan Eye — Whenever one or more OTHER
// creatures and/or artifacts you control die, draw a card." — the creature
// that dies here is deliberately NOT G'raha Tia itself (a separate real
// creature, Town Greeter), matching the printed "other" restriction; G'raha
// survives untouched.

import { gRahaTia } from './definition';
import { basicLandsFor } from '../../mana';
import { checkStateBasedActions } from '../../sba';
import { effectivePT } from '../../state';
import type { TraceResult } from '../../harness';
import { resolveCombatDamage } from '../../engine';
import {
  setupEnginePilot,
  pilotActions,
  pilotCast,
  pilotResolveTop,
  advanceToPlayersNextMain1,
  advanceToDeclareAttackersStep,
  advanceOneStep,
  pilotDeclareAttackers,
  pilotDeclareBlockers,
  pilotFireTrigger,
  finishEnginePilotTrace,
  type EnginePilotSetup,
} from '../../engine-trace';

export function runEngineScenarios(): TraceResult[] {
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{4}{W}'), libraryCount: 8 },
    opponents: [{ libraryCount: 8 }],
  };
  const pilot = setupEnginePilot(setup);

  const grahaReal = pilot.state.addCard(pilot.you, 'Hand', {
    name: gRahaTia.name,
    types: ['Creature'],
    subtypes: ['Cat', 'Archer'],
    keywords: gRahaTia.keywords,
    basePower: gRahaTia.pt?.[0],
    baseToughness: gRahaTia.pt?.[1],
  });
  const actions = pilotActions(pilot, grahaReal.id);
  const ctx = pilot.ctxFor(grahaReal);

  // Cast G'raha Tia ({4}{W}), real mana payment
  pilotCast(pilot, grahaReal, gRahaTia, ctx, actions);
  pilotResolveTop(pilot);

  // A real, SEPARATE creature you control (Town Greeter — real fin {1}{G}
  // 1/1 Human Citizen, added directly rather than cast; its own real ETB
  // text never fires here, only its stat block matters as combat filler) —
  // this is the one that dies below, never G'raha itself.
  const townGreeter = pilot.state.addCard(pilot.you, 'Battlefield', {
    name: 'Town Greeter',
    types: ['Creature'],
    subtypes: ['Human', 'Citizen'],
    basePower: 1,
    baseToughness: 1,
  });
  pilot.log.push({ fn: 'enters', card: townGreeter.name, zone: 'Battlefield', power: 1, toughness: 1, controller: pilot.you.name });

  // A real opponent's 2/2 (Coeurl — same real card dwarven-castle-guard's
  // own scenario already uses as a blocker) — kills Town Greeter outright
  // in blocked combat while taking no lethal damage back.
  const blocker = pilot.state.addCard(pilot.opponents[0]!, 'Battlefield', {
    name: 'Coeurl',
    types: ['Creature'],
    subtypes: ['Cat', 'Beast'],
    basePower: 2,
    baseToughness: 2,
  });
  pilot.log.push({ fn: 'enters', card: blocker.name, zone: 'Battlefield', power: 2, toughness: 2, controller: pilot.opponents[0]!.name });

  // Real turn passage — summoning sickness clears for Town Greeter
  advanceToPlayersNextMain1(pilot, pilot.you);

  advanceToDeclareAttackersStep(pilot);
  pilotDeclareAttackers(pilot, [townGreeter], 'Declare Town Greeter as attacker');
  advanceOneStep(pilot);
  pilotDeclareBlockers(pilot, [{ blocker, attacker: townGreeter }]);
  pilot.beginStep('Resolve lethal combat damage (704.5g SBA) — Town Greeter dies, Coeurl survives');
  const attackerPower = effectivePT(pilot.state, townGreeter)[0];
  const blockerPower = effectivePT(pilot.state, blocker)[0];
  resolveCombatDamage(pilot.engine);
  if (attackerPower > 0) pilot.log.push({ fn: 'dealDamage', source: townGreeter.name, target: blocker.name, amount: attackerPower });
  if (blockerPower > 0) pilot.log.push({ fn: 'dealDamage', source: blocker.name, target: townGreeter.name, amount: blockerPower });
  const sbaResult = checkStateBasedActions(pilot.state, pilot.engine.players);
  for (const destroyed of sbaResult.destroyed) {
    const controllerName = pilot.state.players.get(destroyed.controllerId)!.name;
    pilot.log.push({ fn: 'destroy', target: destroyed.name, controller: controllerName });
  }

  // G'raha's own real trigger — a real OTHER creature you control just died
  // (Town Greeter, above); fired manually once the real death has already
  // happened, same "no auto-fire" pattern every onDies-class trigger in this
  // engine already uses.
  if (townGreeter.zone === 'Graveyard') pilotFireTrigger(pilot, gRahaTia, ctx, actions, 'onOtherPermanentsDie');

  const result =
    "G'raha Tia is cast and enters the battlefield; a real separate creature you control (Town Greeter) attacks, is blocked by a real 2/2 (Coeurl) and dies in genuine lethal combat (704.5g) while G'raha survives untouched — G'raha's own The Allagan Eye trigger then fires for real, drawing a card.";
  return [
    finishEnginePilotTrace(pilot, setup, "real engine playthrough: cast -> real other-creature combat death -> onOtherPermanentsDie", result),
  ];
}

gaelicat.source:
import type { CardDefinition } from '../../card';

export const gaelicat: CardDefinition = {
  name: 'Gaelicat',
  manaCost: '{2}{W}',
  typeLine: 'Creature — Cat',

  // Real printed base P/T (data/fin/fin_scryfall.json) — without this,
  // state.ts's own addCard silently defaults to a fake 1/1 (same real gap
  // adelbert-steiner's own `pt` field closes).
  pt: [1, 3],
  keywords: ['Flying', 'Vigilance'],
  // A conditional continuous P/T ability, presence-gated — a different
  // shape than adelbert-steiner's own count-scaling `ptFormula` CDA (a
  // fixed on/off threshold, not "+X per N controlled"), so it doesn't fit
  // that field; stays real text rather than an invented threshold-CDA
  // mechanism this model doesn't have yet.
  staticAbilities: ['As long as you control two or more artifacts, this creature gets +2/+0.'],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header). Gaelicat has
// no triggers/resolvable effects of its own to pilot — its only real text
// beyond the bare printed Flying/Vigilance keywords is a conditional
// layer-7a CDA ("As long as you control two or more artifacts, this
// creature gets +2/+0"). Unlike Adelbert Steiner's own count-scaling
// `ptFormula` CDA, this is a THRESHOLD-gated shape this engine has no
// `ptFormula` variant for (see definition.ts's own comment, and
// `card.ts`'s `CardDefinition.ptFormula` doc comment) — so this trace
// deliberately demonstrates BOTH halves honestly: (1) the condition itself
// (2+ real Artifact permanents you control) is real, observable board
// state, via genuine logged `isArtifact()` reads; (2) `effectivePT` — the
// same real, live layer-7a read Steiner's own scenario uses — stays at
// Gaelicat's unmodified printed 1/3 even with 2 real artifacts present,
// which is the honest, documented engine gap, not a fabricated bonus.

import { gaelicat } from './definition';
import { basicLandsFor } from '../../mana';
import { effectivePT } from '../../state';
import { loggingCard } from '../../harness';
import type { TraceResult } from '../../harness';
import { setupEnginePilot, pilotActions, pilotCast, pilotResolveTop, finishEnginePilotTrace, type EnginePilotSetup } from '../../engine-trace';

export function runEngineScenarios(): TraceResult[] {
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{2}{W}'), libraryCount: 5 },
    opponents: [{ libraryCount: 5 }],
  };
  const pilot = setupEnginePilot(setup);

  // Two real named fin Artifacts (any real printing works — same "a real
  // named card, not a synthetic placeholder" convention ashe-princess-of-
  // dalmasca's own scenario already establishes for a single real artifact).
  pilot.beginStep('Real artifacts already on the battlefield (2, meets the printed threshold)');
  const phoenixDown = pilot.state.addCard(pilot.you, 'Battlefield', { name: 'Phoenix Down', types: ['Artifact'] });
  const elixir = pilot.state.addCard(pilot.you, 'Battlefield', { name: 'Elixir', types: ['Artifact'] });

  const gaelicatReal = pilot.state.addCard(pilot.you, 'Hand', {
    name: gaelicat.name,
    types: ['Creature'],
    subtypes: ['Cat'],
    keywords: gaelicat.keywords,
    basePower: gaelicat.pt?.[0],
    baseToughness: gaelicat.pt?.[1],
  });
  const actions = pilotActions(pilot, gaelicatReal.id);
  const ctx = pilot.ctxFor(gaelicatReal);

  // Cast Gaelicat ({2}{W}), real mana payment
  pilotCast(pilot, gaelicatReal, gaelicat, ctx, actions);
  pilotResolveTop(pilot);

  // Real, per-object type reads — the condition ("you control two or more
  // artifacts") is genuinely observable board state, same logging wrapper
  // (`loggingCard`) every real Card query in this engine goes through.
  pilot.beginStep("Real condition check — 'you control two or more artifacts'");
  const phoenixIsArtifact = loggingCard(pilot.state, phoenixDown, pilot.log).isArtifact();
  const elixirIsArtifact = loggingCard(pilot.state, elixir, pilot.log).isArtifact();

  // Real layer-7a read — same live `effectivePT` Adelbert Steiner's own
  // scenario uses. Honestly reports Gaelicat's UNMODIFIED printed 1/3: this
  // engine has no threshold-gated `ptFormula` variant, so the printed
  // "+2/+0" never actually applies here — a real, documented gap, not
  // fabricated evidence of a bonus that doesn't happen.
  pilot.beginStep('Real layer-7a read — no threshold-CDA machinery, so the +2/+0 does not apply');
  const [power, toughness] = effectivePT(pilot.state, gaelicatReal);
  pilot.log.push({ fn: 'read:getNetPower', card: gaelicat.name, power, toughness });

  const result = `Gaelicat enters with 2 real Artifacts (Phoenix Down, Elixir; confirmed isArtifact()=${phoenixIsArtifact}/${elixirIsArtifact}) already on the battlefield, meeting the printed "two or more artifacts" threshold — but real layer-7a effectivePT still reports Gaelicat's unmodified printed ${power}/${toughness}, since this engine has no threshold-gated CDA machinery to apply the printed +2/+0 (a real, documented gap, same class as scorpion-sentinel/gigantoad's own identically-shaped land-count buffs).`;
  return [finishEnginePilotTrace(pilot, setup, 'real engine playthrough: 2 real artifacts present -> cast -> real condition/CDA reads (gap documented)', result)];
}

