import type { CardDefinition, Effect } from '../../card';

export const iceMagic: CardDefinition = {
  name: 'Ice Magic',
  manaCost: '{1}{U}',
  typeLine: 'Instant',

  // Real K:Tiered (SP$ Charm with a per-mode ModeCost$) — an ADDITIONAL
  // cost that varies per mode chosen, not a genuine MTG "choose one" (a
  // real modal spell has no per-mode cost). `modal`'s `describe`/`effects`
  // shape still captures "which branch resolves," so it's reused here even
  // though the cost distinction itself isn't tracked (no field on
  // `modal`'s modes carries a cost) — the same "documentary text, no
  // mechanical enforcement" trade this codebase already accepts elsewhere
  // (e.g. `optional`/`notSelf` fields on other Effect kinds).
  effects: [
    {
      kind: 'modal',
      modes: [
        {
          describe: "Blizzard — {0} — Return target creature to its owner's hand.",
          // Real ValidTgts$ Creature has no owner restriction (any
          // player's creature) — `owner` omitted (fixed 2026-09-06, see
          // card.ts's own `move` case) means the real combined,
          // unrestricted pool.
          effects: [{ kind: 'move', from: 'Battlefield', to: 'Hand', qty: 1, validType: 'creature', target: true } satisfies Effect],
        },
        {
          describe: "Blizzara — {2} — Target creature's owner puts it on their choice of the top or bottom of their library.",
          // Real AlternativeDecider$ TargetedOwner — the TARGET's owner
          // (not the caster) chooses top/bottom; this model has no
          // player-decision engine anywhere and `move`'s own Library
          // destination carries no top/bottom position field, so only the
          // real zone change (to Library) is tracked, not the choice.
          effects: [{ kind: 'move', from: 'Battlefield', to: 'Library', qty: 1, validType: 'creature', target: true } satisfies Effect],
        },
        {
          describe: "Blizzaga — {5}{U} — Target creature's owner shuffles it into their library.",
          // "Shuffle" has no observable consequence anything downstream
          // reads in this model (no library-order tracking beyond
          // top/bottom-of-array) — same "not modeled, no consequence"
          // treatment from-father-to-son's own comment already documents.
          effects: [{ kind: 'move', from: 'Battlefield', to: 'Library', qty: 1, validType: 'creature', target: true } satisfies Effect],
        },
      ],
    } satisfies Effect,
  ],
};

ignis-scientia.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';
import { TOKENS } from '../../tokens.ts';

export const ignisScientia: CardDefinition = {
  name: 'Ignis Scientia',
  manaCost: '{1}{G}{U}',
  typeLine: 'Legendary Creature — Human Advisor',

  pt: [2, 2],

  triggers: [
    {
      // "Look at the top six cards of your library. You may put a land
      // card from among them onto the battlefield tapped. Put the rest on
      // the bottom in a random order." Real Forge `DigEffect` shape, but
      // this model's own `dig` Effect kind only supports `validType:
      // 'artifact' | 'any'` (no `'land'`) AND always routes its found
      // cards to HAND (`state.ts`'s own `GameState.dig` hardcodes
      // `move(card, 'Hand')`), never Battlefield — neither matches this
      // card's real "onto the battlefield" destination. The plain
      // untargeted `move` shape reach-the-horizon/prishe-s-wanderings/
      // gladiolus-amicitia already use for "search for a land, put it onto
      // the battlefield" is the closer real-outcome fit (loses the
      // "top six only"/"tapped"/"rest to bottom" nuance, same documentary-
      // loss class those cards already flag, and hits the same no-land-
      // typed-library-filler gap they note too).
      name: 'onEnter',
      effects: [{ kind: 'move', owner: 'you', from: 'Library', to: 'Battlefield', qty: 1, validType: 'land' } satisfies Effect],
    },
  ],

  activationCost: '{1}{G}{U}, {T}',
  effects: [
    {
      // "Exile target card from a graveyard. If a creature card was exiled
      // this way, create a Food token" — the token creation is gated on
      // what the CHOSEN target actually was, which no combination of
      // `move`+`createToken` can express declaratively (nothing feeds one
      // effect's real outcome into the next's condition) — same shape
      // sidequest-catch-a-fish-cooking-campsite's own upkeep trigger
      // already established this exact pattern for.
      kind: 'custom',
      describe: "exile target card from a graveyard; if a creature card was exiled this way, create a Food token",
      run: (ctx: EffectContext, actions: Actions) => {
        const pool = [...ctx.you.getCardsIn('Graveyard'), ...ctx.opponents.flatMap((p) => p.getCardsIn('Graveyard'))];
        if (pool.length === 0) return;
        const target = actions.chooseTarget(pool);
        const wasCreature = target.isCreature();
        actions.moveTo(target, 'Exile');
        if (wasCreature) actions.createToken(ctx.you, TOKENS.c_a_food_sac, 1);
      },
    } satisfies Effect,
  ],
};

