        {
          kind: 'custom',
          describe: 'return target permanent card with mana value 3 or less from your graveyard to the battlefield',
          run: (ctx, actions) => {
            const pool = ctx.you.getCardsIn('Graveyard').filter((c) => c.getCMC() <= 3);
            if (pool.length === 0) return;
