ultima.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const ultima: CardDefinition = {
  name: 'Ultima',
  manaCost: '{3}{W}{W}',
  typeLine: 'Sorcery',

  effects: [
    {
      // Real `SP$ DestroyAll | ValidCards$ Artifact,Creature` — Forge's own
      // real UNCHOSEN mass-destroy ApiType, genuinely different from the
      // `destroy` Effect kind here (which mirrors the targeted
      // `DestroyEffect`: a player-CHOSEN pool of `qty` picks). `destroy`'s
      // own `validType` also only offers 'permanent'|'creature' — neither
      // covers "artifacts AND creatures, but not lands/enchantments."
      // `custom`, looping the real `destroy` action over the real
      // battlefield-wide pool filtered by `isArtifact()`/`isCreature()`, is
      // the honest shape — every primitive here (`getCardsIn`, the two
      // predicates, `actions.destroy`) already exists; this just isn't a
      // "chosen N targets" loop the declarative `destroy` kind models.
      kind: 'custom',
      describe: 'destroy all artifacts and creatures',
      run: (ctx: EffectContext, actions: Actions) => {
        const pool = [...ctx.you.getCardsIn('Battlefield'), ...ctx.opponents.flatMap((p) => p.getCardsIn('Battlefield'))].filter(
          (c) => c.isArtifact() || c.isCreature()
        );
        for (const card of pool) actions.destroy(card);
      },
    } satisfies Effect,
    {
      // "End the turn." — a real turn-ending game action (exile the stack,
      // discard down to maximum hand size, damage/until-end-of-turn effects
      // end) — no turn-ending machinery anywhere in this model (turn.ts
      // tracks phases/steps, not a way to jump straight to cleanup) — real
      // text only, same honest no-op treatment crystal-fragments-summon-
      // alexander's own damage-prevention chapters get for a mechanic this
      // model has no machinery for at all.
      kind: 'custom',
      describe: 'end the turn (exile the stack, discard down to maximum hand size, "until end of turn" effects end) — no turn-ending machinery in this model',
      run: () => {},
    } satisfies Effect,
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header) — one real
// scenario, a genuinely SYMMETRIC board wipe: both players control a real
// (non-token) artifact and a real (non-token) creature, plus a land that
// should survive untouched — proving this is a real, unconditional,
// UNTARGETED mass-destroy (`SP$ DestroyAll | ValidCards$ Artifact,Creature`,
// not a chosen-target loop) that hits BOTH sides, not just the caster's own
// opponent, and doesn't touch anything outside its own stated scope (lands).
//
// Non-token targets, same reasoning fate-of-the-sun-cryst's own scenario
// documents: `card.ts`'s `destroy` case logs a literal `fn:'destroy'` line
// only for a real (non-token) permanent — a token instead logs
// `ceasesToExist`, which can't back a real `event:'destroy'` ACT fact as
// trace evidence.
//
// "End the turn" is NOT exercised here — no turn-ending machinery exists in
// this model (see definition.ts's own comment on that effect); real text
// only, an honest documented gap, not something a scenario can demonstrate.

import { ultima } from './definition';
import { basicLandsFor } from '../../mana';
import type { TraceResult } from '../../harness';
import { setupEnginePilot, pilotActions, pilotCast, pilotResolveTop, finishEnginePilotTrace, type EnginePilotSetup } from '../../engine-trace';

function wipesArtifactsAndCreaturesOnBothSides(): TraceResult {
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{3}{W}{W}') },
    opponents: [{}],
  };
  const pilot = setupEnginePilot(setup);

  // Your own real artifact and creature (data/fin/fin_scryfall.json #52,
  // #19) — both should be destroyed by your own spell too, since the real
  // oracle text has no controller restriction.
  const yourLance = pilot.state.addCard(pilot.you, 'Battlefield', { name: "Dragoon's Lance", types: ['Artifact'], subtypes: ['Equipment'], cmc: 2 });
  pilot.log.push({ fn: 'enters', card: yourLance.name, zone: 'Battlefield', controller: pilot.you.name });
  const yourCreature = pilot.state.addCard(pilot.you, 'Battlefield', { name: 'Dwarven Castle Guard', types: ['Creature'], subtypes: ['Dwarf', 'Soldier'], basePower: 2, baseToughness: 1, cmc: 2 });
  pilot.log.push({ fn: 'enters', card: yourCreature.name, zone: 'Battlefield', power: yourCreature.basePower, toughness: yourCreature.baseToughness, controller: pilot.you.name });

  // The opponent's own real artifact and creature (data/fin/fin_scryfall.json
  // #22, #38's own neighbor set) — Coeurl is the same real, non-token
  // permanent fate-of-the-sun-cryst's own scenario already uses as an
  // opponent's destroy target.
  const opp = pilot.opponents[0]!;
  const oppPhoenixDown = pilot.state.addCard(opp, 'Battlefield', { name: 'Phoenix Down', types: ['Artifact'], cmc: 1 });
  pilot.log.push({ fn: 'enters', card: oppPhoenixDown.name, zone: 'Battlefield', controller: opp.name });
  const oppCreature = pilot.state.addCard(opp, 'Battlefield', { name: 'Coeurl', types: ['Creature'], subtypes: ['Cat', 'Beast'], basePower: 2, baseToughness: 2, cmc: 2 });
  pilot.log.push({ fn: 'enters', card: oppCreature.name, zone: 'Battlefield', power: oppCreature.basePower, toughness: oppCreature.baseToughness, controller: opp.name });

  // Real, untouched lands on both sides, to demonstrate the wipe genuinely
  // stops at "artifacts and creatures" rather than everything.
  pilot.state.addCard(pilot.you, 'Battlefield', { name: 'Plains', types: ['Land'], subtypes: ['Plains'], manaAbility: 'W' });
  pilot.state.addCard(opp, 'Battlefield', { name: 'Plains', types: ['Land'], subtypes: ['Plains'], manaAbility: 'W' });

  const cardReal = pilot.state.addCard(pilot.you, 'Hand', { name: ultima.name, types: [] });
  const actions = pilotActions(pilot, cardReal.id);
  const ctx = pilot.ctxFor(cardReal);

  pilotCast(pilot, cardReal, ultima, ctx, actions);
  pilotResolveTop(pilot);

  const result =
    "Destroys all four real artifacts/creatures on both battlefields — your own Dragoon's Lance and Dwarven Castle Guard, AND the opponent's own Phoenix Down and Coeurl — a genuinely symmetric, untargeted wipe (no controller restriction in the real text). Both real Plains survive untouched. \"End the turn\" is real text only — no turn-ending machinery in this model, so it isn't (and can't be) exercised here.";
  return finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast -> resolve (Destroy all artifacts and creatures)', result);
}

export function runEngineScenarios(): TraceResult[] {
  return [wipesArtifactsAndCreaturesOnBothSides()];
}

ultima-origin-of-oblivion.source:
import type { CardDefinition, Effect } from '../../card';

export const ultimaOriginOfOblivion: CardDefinition = {
  name: 'Ultima, Origin of Oblivion',
  manaCost: '{5}',
  typeLine: 'Legendary Creature — God',

  keywords: ['Flying'],
  staticAbilities: [
    // The continuous consequence of the blight counter ("loses all land
    // types/abilities, has T: Add C") is a real replacement/static-grant
    // effect tied to a counter's presence — this model has no continuous-
    // effect-tied-to-a-counter machinery (layers.ts only tracks P/T and
    // added types, not ability removal/grant), so left as text, same
    // treatment Kain's own "Jump" static gets.
    "For as long as a land has a blight counter on it, it loses all land types and abilities and has \"{T}: Add {C}.\"",
    // A real triggered mana-doubling effect on every land tap. Kept as text
    // here too (typeLine/full-ability-text parity with every other card),
    // but — unlike the counter-tied static grant above, which genuinely has
    // no engine machinery to hook into — the "add an additional {C}" HALF
    // of this is a plain, already-real `kind:'addMana'` Effect (same shape
    // Elvish Archdruid's own "{T}: Add {G} for each Elf you control" uses),
    // so it's ALSO wired as the real `onTapLandForC` trigger below. No
    // trigger in this model auto-fires off "a land you control was tapped
    // for mana" (`Trigger.on` only recognizes 'enter'/'upkeep'/'endStep') —
    // same as every other named trigger pool-wide (`onAttack` right below
    // included), this one is manually fired by a scenario, not
    // auto-detected off a real land-tap action.
    'Whenever you tap a land for {C}, add an additional {C}.',
  ],

  triggers: [
    {
      name: 'onAttack',
      effects: [{ kind: 'putCounterTarget', validType: 'land', counterType: 'blight', amount: 1, qty: 1 } satisfies Effect],
    },
    {
      // Fired manually right after a scenario pilots a real land being
      // tapped for {C} — see scenarios.ts. Only models the "additional {C}"
      // Ultima itself adds; the land's own base {C} is its own real
      // addMana line, not this trigger's job to reproduce.
      name: 'onTapLandForC',
      effects: [{ kind: 'addMana', color: 'C', amount: 1 } satisfies Effect],
    },
  ],
};


// ============================================================
// scenarios.ts — this card's own real engine-piloted trace
// ============================================================

// Real engine-piloted trace (see engine-trace.ts's own header). Neither
// onAttack nor onTapLandForC auto-fires in this engine (Trigger.on only
// recognizes 'enter'|'upkeep'|'endStep') — so this pilots a real attack
// declaration and a real land-tap-for-{C} activation, then fires each
// trigger manually right after.

import { ultimaOriginOfOblivion } from './definition';
import { adventurersInn } from '../adventurer-s-inn/definition';
import { basicLandsFor } from '../../mana';
import type { TraceResult } from '../../harness';
import type { CardDefinition, Effect } from '../../card';
import {
  setupEnginePilot,
  pilotActions,
  pilotCast,
  pilotResolveTop,
  pilotActivate,
  advanceToPlayersNextMain1,
  advanceToDeclareAttackersStep,
  pilotDeclareAttackers,
  pilotFireTrigger,
  finishEnginePilotTrace,
  type EnginePilotSetup,
} from '../../engine-trace';

// Adventurer's Inn's own real, single, unambiguous "{T}: Add {C}." line
// (its only static ability — see its own definition.ts) — no mana-producing
// Effect/Action exists on the REAL card (documented STILL-DEFERRED gap, same
// as every other plain Town-land mana ability pool-wide), so this is a
// throwaway, scenario-local CardDefinition pairing that one real printed
// line with a real `kind:'addMana'` Effect (the same shape Elvish
// Archdruid's own activated mana ability already proves executable),
// scoped entirely to this file — adventurer-s-inn's own definition.ts is
// untouched.
const adventurersInnManaAbility: CardDefinition = {
  name: adventurersInn.name,
  manaCost: '',
  typeLine: adventurersInn.typeLine,
  activationCost: '{T}',
  effects: [{ kind: 'addMana', color: 'C', amount: 1 } satisfies Effect],
};

export function runEngineScenarios(): TraceResult[] {
  const setup: EnginePilotSetup = {
    you: { basicLands: basicLandsFor('{5}'), libraryCount: 5 },
    opponents: [{ basicLands: ['Forest'], libraryCount: 5 }],
  };
  const pilot = setupEnginePilot(setup);

  const ultimaReal = pilot.state.addCard(pilot.you, 'Hand', {
    name: ultimaOriginOfOblivion.name,
    types: ['Creature'],
    subtypes: ['God', 'Legendary'],
    keywords: ultimaOriginOfOblivion.keywords,
  });
  const actions = pilotActions(pilot, ultimaReal.id);
  // "Target land" has no owner restriction at all (real oracle text) — the
  // real chooseTarget default (pool[0] of an unrestricted combined pool,
  // `you` always first) would otherwise blight YOUR OWN land instead of the
  // opponent's, contradicting this scenario's own story (a genuine, if
  // legal, choice this pilot script makes on purpose, same reasoning
  // Bahamut's own preferTarget uses).
  const opp = pilot.opponents[0]!;
  const ctx = pilot.ctxFor(ultimaReal, { preferTarget: (c) => c.getController().getId() === opp.id });

  // Cast Ultima ({5}), real mana payment
  pilotCast(pilot, ultimaReal, ultimaOriginOfOblivion, ctx, actions);
  // Resolves (no ETB trigger)
  pilotResolveTop(pilot);

  // Real turn passage — summoning sickness (302.6) clears
  advanceToPlayersNextMain1(pilot, pilot.you);

  // Real attack declaration (508.1)
  advanceToDeclareAttackersStep(pilot);
  pilotDeclareAttackers(pilot, [ultimaReal], 'Declare Ultima as attacker');

  // onAttack fired manually — puts a real blight counter on the opponent's only land
  pilotFireTrigger(pilot, ultimaOriginOfOblivion, ctx, actions, 'onAttack');

  // A real Adventurer's Inn, already resolved on your battlefield (added
  // directly, same "bystander permanent" convention every other scenario's
  // own non-protagonist permanents use — no `enteredThisTurn` stamp, so no
  // summoning-sickness gate applies to its own {T} cost either).
  const innReal = pilot.state.addCard(pilot.you, 'Battlefield', {
    name: adventurersInn.name,
    types: ['Land'],
    subtypes: ['Town'],
    manaAbility: 'C',
  });
  const innCtx = pilot.ctxFor(innReal);
  const innActions = pilotActions(pilot, innReal.id);
  // Real {T}: Add {C} activation (602.1) — tap the Inn for its own {C}.
  pilotActivate(pilot, pilot.you, innReal, adventurersInnManaAbility, innCtx, innActions, "Tap Adventurer's Inn for {C}");
  pilotResolveTop(pilot);
  // Ultima's own real "Whenever you tap a land for {C}, add an additional
  // {C}" — fired manually right after the real land tap above, adding a
  // real second {C} via the same `kind:'addMana'` Effect shape.
  pilotFireTrigger(pilot, ultimaOriginOfOblivion, ctx, actions, 'onTapLandForC', "Ultima triggers: add an additional {C}");

  const result =
    'Ultima enters, real turn passage clears summoning sickness, then really attacks (508.1), putting a real blight counter on the opponent\'s only land (whose granted "{T}: Add {C}" stays real printed text with no engine machinery behind it). Separately, a real Adventurer\'s Inn is tapped for its own real {C}, and Ultima\'s own mana-doubling trigger fires right after, adding a real additional {C}.';
  return [finishEnginePilotTrace(pilot, setup, 'real engine playthrough: cast -> turn passage -> real attack -> onAttack -> real land tap -> onTapLandForC', result)];
}

