export const ultimeciaTemporalThreat: CardDefinition = {
  name: 'Ultimecia, Temporal Threat',
  manaCost: '{4}{U}{U}',
  typeLine: 'Legendary Creature — Human Warlock',

  pt: [4, 4],

  triggers: [
    {
      // "tap all creatures your opponents control" — real `DB$ TapAll`, a
      // genuine board-wide batch with no player choice at all; `tapTarget`'s
      // own declarative shape only ever picks ONE chosen target (see
      // card.ts's own doc comment: `TapEffect`/`TapAllEffect` are two real,
      // distinct Forge classes, and only the single-target one has a
      // declarative Effect kind here) — `custom` composing the real
      // `actions.tap` over every opponent creature instead, same
      // "no new capability, just an unbuilt declarative shape" reasoning
      // sephiroth-planet-s-heir's own opponents' -2/-2 custom effect uses
      // for the identical gap.
      name: 'onEnter',
      effects: [
        {
          kind: 'custom',
          describe: 'tap all creatures your opponents control',
          run: (ctx: EffectContext, actions: Actions) => {
            for (const opp of ctx.opponents) for (const creature of opp.getCreaturesInPlay()) actions.tap(creature);
          },
        } satisfies Effect,
      ],
    },
    {
      name: 'onDealsCombatDamage',
      effects: [{ kind: 'drawCard' } satisfies Effect],
    },
  ],
};

ultimecia-time-sorceress-ultimecia-omnip.source:
import type { CardDefinition, Effect } from '../../card';

// Real script (ultimecia_time_sorceress_ultimecia_omnipotent.txt): a
// transforming DFC, same `SetState | Mode$ Transform` shape (exile-then-
// return standing in for it) serah-farron/terra-magical-adept already use.
export const ultimeciaTimeSorceress: CardDefinition = {
  name: 'Ultimecia, Time Sorceress',
  manaCost: '{3}{U}{B}',
  typeLine: 'Legendary Creature — Human Warlock',

  pt: [4, 5],

  triggers: [
    { name: 'onEnterOrAttacks', effects: [{ kind: 'surveil', qty: 2 } satisfies Effect] },
    {
      // "At the beginning of your end step, you may pay {4}{U}{U}{B}{B}
      // and exile eight cards from your graveyard. If you do, transform
      // NICKNAME." The mana payment is documentary-only text (same
      // convention every activation-cost mana string already gets — no
      // field anywhere tracks a mana pool); exiling eight graveyard cards
      // is a real, observable zone change, modeled with the declarative
      // batch `move`. The transform itself is the same exile-then-return
      // approximation this file's own header describes.
      name: 'onEndStep',
      effects: [
        { kind: 'move', owner: 'you', from: 'Graveyard', to: 'Exile', qty: 8, validType: 'any' } satisfies Effect,
        {
          kind: 'custom',
          describe: 'pay {4}{U}{U}{B}{B}; transform Ultimecia into Ultimecia, Omnipotent',
          run: (ctx, actions) => {
            actions.moveTo(ctx.self, 'Exile');
            actions.moveTo(ctx.self, 'Battlefield');
          },
        } satisfies Effect,
      ],
    },
  ],

  backFace: {
    name: 'Ultimecia, Omnipotent',
    manaCost: '',
    typeLine: 'Legendary Creature — Nightmare Warlock',

    pt: [7, 7],
    keywords: ['Menace'],
    // "Time Compression — When this creature transforms into CARDNAME,
    // take an extra turn after this one." No `Effect` kind exists anywhere
    // for "take an extra turn" (`interfaces.ts` has no such action either,
    // real or convenience) — genuinely out of scope. No `triggers` here
    // rather than a fabricated workaround; flagged to the parent as a gap.
  },
};

ultros-obnoxious-octopus.source:
import type { CardDefinition, Effect, EffectContext, Actions } from '../../card';

export const ultrosObnoxiousOctopus: CardDefinition = {
  name: 'Ultros, Obnoxious Octopus',
  manaCost: '{1}{U}',
  typeLine: 'Legendary Creature — Octopus',

  pt: [2, 1],

  triggers: [
    {
      // Real T:Mode$ SpellCast | ValidSAonCard$ Spell.ManaSpent GE4 —
      // "if at least four mana was spent to cast it" is a real cast-time
      // condition this model has no mana-spent tracking for at all (no
      // Effect/EffectContext field carries how much mana a cast spent
      // anywhere in this batch's read of card.ts/harness.ts); a scenario
      // firing this named trigger already stands in for "the condition was
      // met," same as every other conditional trigger name in this repo
      // (Minwu's own `onLifeGained`, e.g.).
      name: 'onNoncreatureSpellCastGE4Mana',
      effects: [
        {
          // "tap target creature an OPPONENT controls and put a stun
          // counter on IT" — the same chosen object twice. Neither
          // `tapTarget` nor `putCounterTarget` restricts its pool to one
          // player's creatures (both draw from the union of every
          // creature on the battlefield), and nothing ties two separate
          // declarative effects to the SAME chosen target — `custom`,
          // picking one real target from the real opponent-only pool and
          // applying both actions to it, is the honest shape.
          kind: 'custom',
          describe: 'tap target creature an opponent controls and put a stun counter on it',
          run: (ctx: EffectContext, actions: Actions) => {
            const pool = ctx.opponents.flatMap((p) => p.getCreaturesInPlay());
            if (pool.length === 0) return;
            const target = actions.chooseTarget(pool);
            actions.tap(target);
            actions.putCounter(target, 'Stun', 1);
          },
        } satisfies Effect,
      ],
    },
    {
      name: 'onNoncreatureSpellCastGE8Mana',
      effects: [{ kind: 'putCounter', target: 'self', counterType: '+1/+1', amount: 8 } satisfies Effect],
    },
  ],
};

